const STAGE={1:'Знакомство',2:'Первые проекты',3:'Соединяем навыки',4:'Углубление'};
const PS={catalog:'Каталог',planned:'В планах',active:'В работе',paused:'Отложен',done:'Завершён'};
let saveError='',corruptBackup='',undo=[],migrationNote='';
let D=clone(SEED);
const MSTATUS={mastered:'Освоен',progress:'В процессе',todo:'Впереди'};
// Older saves are upgraded in place; the untouched original stays in OLD_KEY and can be downloaded from «Данные».
function upgrade(state){
 const r=Core.migrate(state,SEED,HISTORY);
 const toolIds=new Set(r.state.tools.map(x=>x.id));
 for(const t of SEED.tools){if(!toolIds.has(t.id)){r.state.tools.push(clone(t));toolIds.add(t.id)}}
 for(const [k,v] of Object.entries(SEED.inventory||{})){if(r.state.inventory[k]===undefined&&toolIds.has(k))r.state.inventory[k]=v}
 for(const k of Object.keys(r.state.inventory)){if(!toolIds.has(k))delete r.state.inventory[k]}
 Core.validateState(r.state,SCHEMA);
 return r;
}
function reportText(r){return r?`Каталог обновлён: новых карточек ${r.added}, обновлено ${r.updated}${r.kept?`, твои правки сохранены в ${r.kept}`:''}. Опыт и заметки не тронуты.`:''}
try{const raw=localStorage.getItem(KEY);if(raw){try{const o=JSON.parse(raw);const r=upgrade(o.state);D=r.state;if(r.migrated){if(o.state.schemaVersion!==Core.VERSION&&!localStorage.getItem(OLD_KEY))localStorage.setItem(OLD_KEY,raw);migrationNote=reportText(r.report)||'Сохранение обновлено до новой версии.';undo=[]}else undo=Array.isArray(o.undo)?o.undo.slice(-3):[]}catch(e){corruptBackup=raw;saveError='Сохранение не прочитано: '+e.message+'. Исходные данные сохранены для выгрузки в разделе «Данные». Сейчас показан стартовый профиль.'}}}catch{saveError='Браузер не разрешил постоянное хранение. Карта работает, но перед закрытием нужно экспортировать JSON.'}
const U={page:'home',branch:null,search:'',mfilter:'all',group:'all',status:'all',projectBranch:'all',simple:false,toolBranch:'all',toolStatus:'all',journalKind:'all',mode:'experience',aiScope:'wood',aiText:'',proposal:null,proposalSelected:[],aiBusy:false,aiConsent:false,health:null,aiMessage:'',chatPackage:'',packageMode:null,packageRevision:null,drafts:{},openModal:null,serverStatus:{status:'checking',message:''},serverBackups:[],serverGit:null,serverLastSaved:null,selectedBackup:null};
const ICONS={
compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.7 5.3L8 16l2.7-5.3Z"/>',wood:'<path d="m4 5 14-2 2 15-14 3Z"/><path d="m9 6 2 11m3-12 2 11M5 10l14-2M6 16l13-2"/>',gear:'<path d="m9 3-1 3-3 1-2 3 2 3v3l3 2 1 3h5l1-3 3-1 2-3-2-3V8l-3-2-1-3Z"/><circle cx="11.5" cy="12" r="3"/>',layers:'<path d="m3 8 9-5 9 5-9 5Zm0 4 9 5 9-5M3 16l9 5 9-5"/>',brick:'<path d="M3 4h18v16H3zM3 9h18M3 15h18M9 4v5M15 9v6M9 15v5"/>',needle:'<path d="M18 3 5 19l-2 2 2-5L16 3q3-2 2 2Z"/><path d="m15 6 2-2M10 17q0 6 8 3"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>',chip:'<rect x="6" y="6" width="12" height="12" rx="2"/><path d="M9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4"/><path d="M10 10h4v4h-4z"/>',drop:'<path d="M12 2S5 10 5 15a7 7 0 0 0 14 0C19 10 12 2 12 2Z"/><path d="M8 15q0 4 4 4"/>',house:'<path d="m2 11 10-8 10 8M5 9v12h14V9M9 21v-7h6v7"/>',leaf:'<path d="M20 3C8 2 2 7 4 14c2 8 15 6 16-11Z"/><path d="M3 22 16 8M8 17l-1-6m5 2 5 1"/>',wheel:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/><path d="M12 3v6m0 6v6m9-9h-6m-6 0H3"/>',cube:'<path d="m12 2 9 5v10l-9 5-9-5V7Zm0 10v10M3 7l9 5 9-5M7.5 4.5l9 5v5"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5ZM20 2v4m-2-2h4"/>',map:'<path d="m3 5 6-3 6 3 6-3v17l-6 3-6-3-6 3ZM9 2v17m6-14v17"/>',book:'<path d="M12 5C9 2 5 2 2 3v16c4-1 7 0 10 2 3-2 6-3 10-2V3c-3-1-7-1-10 2Zm0 0v16"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/>',flag:'<path d="M5 22V3m0 0q4-3 8 0t7 0v10q-3 3-7 0t-8 0"/>',tools:'<path d="M14 4a6 6 0 0 0-7 8l-5 6 4 4 6-6a6 6 0 0 0 8-7l-4 4-4-4Z"/>',undo:'<path d="M3 9h11a7 7 0 0 1 0 14M3 9l5-5M3 9l5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',save:'<path d="M4 3h13l4 4v14H3V3Zm3 0v6h10V3M7 21v-8h10v8"/>',shield:'<path d="m12 2 9 4v6q0 6-9 10-9-4-9-10V6Zm-4 9 3 3 5-6"/>',edit:'<path d="m4 16 12-12 4 4L8 20H4Zm10-10 4 4"/>'};
const ico=(n,c='')=>`<svg class="icon ${c}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.compass}</svg>`;
const btn=(text,action,id='',cls='',icon='')=>`<button class="btn ${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${icon?ico(icon):''}${text}</button>`;
const skillWord=n=>(n%100>=11&&n%100<=14)?'навыков':n%10===1?'навык':n%10>=2&&n%10<=4?'навыка':'навыков';
const tag=(text,cls='')=>`<span class="tag ${cls}">${esc(text)}</span>`;
const riskTag=r=>tag(RISK[r],r==='pro'?'red':r==='low'?'green':'');
const activeSkills=()=>D.skills.filter(x=>!x.archived),activeBranches=()=>D.branches.filter(x=>!x.archived),activeProjects=()=>D.projects.filter(x=>!x.archived);
const getSkill=id=>D.skills.find(x=>x.id===id),getProject=id=>D.projects.find(x=>x.id===id),getBranch=id=>D.branches.find(x=>x.id===id),getTool=id=>D.tools.find(x=>x.id===id);
const sLink=id=>{const s=getSkill(id);return s?`<button class="linkbutton small" data-action="skill" data-id="${esc(id)}">${esc(s.title)}</button>`:esc(id)};
const bTag=id=>{const b=getBranch(id);return b?`<button class="tag" data-action="branch" data-id="${esc(id)}">${esc(b.title)}</button>`:''};
let serverSaveTimer=null;
function updateSaveBadge(){
 const el=$('#save-indicator');if(!el)return;
 const s=U.serverStatus||{status:'offline'};
 if(s.status==='saving'){el.className='save-indicator saving';el.innerHTML=`${ico('clock')}<span>Сохранение…</span>`;el.title='Отправка данных на сервер'}
 else if(s.status==='synced'){el.className='save-indicator synced';el.innerHTML=`${ico('save')}<span>Сервер · r${D.revision}</span>`;el.title=`Сохранено на сервере в data/save.json${s.gitCommitted?' и в Git':''}`}
 else if(s.status==='offline'){el.className='save-indicator offline';el.innerHTML=`${ico('shield')}<span>Локально</span>`;el.title='Сервер не запущен. Изменения сохраняются в браузере.'}
 else if(s.status==='error'){el.className='save-indicator error';el.innerHTML=`${ico('close')}<span>Сбой сервера</span>`;el.title=s.message||'Ошибка сохранения на сервере'}
}
async function sendServerSave(note){
 if(!window.location.protocol.startsWith('http')){U.serverStatus={status:'offline',message:'Автономный режим'};updateSaveBadge();return null}
 U.serverStatus={status:'saving',message:'Сохранение…'};updateSaveBadge();
 try{
  const payload={app:'svoya-masterskaya',version:Core.VERSION,savedAt:new Date().toISOString(),note:note||'',state:D,undo:undo.slice(-3)};
  const res=await fetch('/api/save',{method:'POST',headers:{'Content-Type':'application/json',...accessHeaders()},body:JSON.stringify(payload)});
  if(!res.ok){const err=await res.json().catch(()=>({}));throw new Error(err.error||`HTTP ${res.status}`)}
  const data=await res.json();
  U.serverStatus={status:'synced',message:`Сохранено на сервере (r${data.revision})`,gitCommitted:data.gitCommitted};
  U.serverLastSaved=data.savedAt;updateSaveBadge();return data;
 }catch(e){
  U.serverStatus={status:'error',message:e.message};updateSaveBadge();console.warn('Сервер сохранения недоступен:',e.message);return null;
 }
}
function persist(label){
 try{localStorage.setItem(KEY,JSON.stringify({app:'svoya-masterskaya',version:Core.VERSION,state:D,undo:undo.slice(-3)}));if(!corruptBackup)saveError=''}catch{saveError='Изменения пока только в памяти: браузер не сохранил их. Экспортируй JSON перед закрытием.'}
 if(window.location.protocol.startsWith('http')){
  U.serverStatus={status:'saving',message:'Сохранение…'};updateSaveBadge();
  clearTimeout(serverSaveTimer);
  serverSaveTimer=setTimeout(()=>{sendServerSave(label||'Автосохранение')},250);
 }
 return true;
}
async function refreshBackups(){
 if(!window.location.protocol.startsWith('http'))return null;
 try{
  const res=await fetch('/api/backups',{headers:accessHeaders()});
  if(!res.ok)return null;
  const data=await res.json();
  U.serverBackups=data.backups||[];
  U.serverGit=data.git||null;
  return data;
 }catch(e){console.warn('Не удалось загрузить бэкапы:',e);return null}
}
async function initServerSync(){
 if(!window.location.protocol.startsWith('http')){U.serverStatus={status:'offline',message:'Автономный режим'};updateSaveBadge();return}
 try{
  const [saveRes,backupsData]=await Promise.all([fetch('/api/save',{headers:accessHeaders()}).catch(()=>null),refreshBackups().catch(()=>null)]);
  if(saveRes&&saveRes.ok){
   const data=await saveRes.json();
   if(data.exists&&data.save&&data.save.state){
    const serverState=data.save.state;
    const localRev=D.revision||0,serverRev=serverState.revision||0;
    if(serverRev>=localRev||corruptBackup||saveError){
     const r=upgrade(serverState);D=r.state;
     undo=Array.isArray(data.save.undo)?data.save.undo.slice(-3):[];
     try{localStorage.setItem(KEY,JSON.stringify({app:'svoya-masterskaya',version:Core.VERSION,state:D,undo}))}catch{}
     saveError='';corruptBackup='';
     U.serverLastSaved=data.savedAt;
     U.serverStatus={status:'synced',message:`Синхронизировано с сервером (r${D.revision})`};
     render();updateSaveBadge();
    }else{
     await sendServerSave('Синхронизация локальных изменений');
    }
   }else{
    await sendServerSave('Первоначальное сохранение на сервере');
    await refreshBackups();render();
   }
  }else{
   U.serverStatus={status:'offline',message:'Сервер недоступен'};updateSaveBadge();
  }
 }catch(e){
  U.serverStatus={status:'offline',message:e.message};updateSaveBadge();
 }
}
function commit(label,change){const before=clone(D);try{change();Core.validateState(D,SCHEMA);undo.push(before);undo=undo.slice(-3);D.revision=before.revision+1;D.audit.push({id:uid('change'),date:new Date().toISOString(),label});D.audit=D.audit.slice(-100);persist();render()}catch(e){D=before;throw e}}
function toast(text,error=false){clearTimeout(U.toastTimer);$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${esc(text)}</div>`;U.toastTimer=setTimeout(()=>$('#toast-root').innerHTML='',6500)}
function download(name,content,type='application/json'){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000)}
function exportState(){download('masterskaya-backup-'+today()+'.json',JSON.stringify({app:'svoya-masterskaya',version:Core.VERSION,exportedAt:new Date().toISOString(),state:D},null,2));toast('Резервная копия подготовлена. Она содержит карту, опыт, заметки и инвентарь.')}
const prog=id=>Core.skillProgress(D,id);
function setMastery(id,fn,label){commit(label,()=>{const m=D.mastery[id]||{mastered:false,checks:[],date:null};fn(m);m.checks.sort((a,b)=>a-b);if(!m.mastered&&!m.checks.length)delete D.mastery[id];else D.mastery[id]=m})}
function toggleMastered(id){const s=getSkill(id),was=prog(id).mastered;setMastery(id,m=>{m.mastered=!was;m.date=was?null:today();if(!was)m.checks=s.criteria.map((_,i)=>i)},(was?'Снята отметка освоения: ':'Навык освоен: ')+s.title);toast(was?'Отметка снята. Опыт в журнале не изменился.':'Навык отмечен освоенным. XP это не меняет — это твоя оценка.')}
// Segmented bar: mastered, then in progress, then what is left.
function masteryBar(st,cls=''){const w=n=>st.count?100*n/st.count:0;return`<div class="mastery-bar ${cls}" role="img" aria-label="Освоено ${st.mastered} из ${st.count}, в процессе ${st.progress}"><span class="m-done" style="width:${w(st.mastered)}%"></span><span class="m-prog" style="width:${w(st.progress)}%"></span></div>`}
function groupStats(skills){const r={count:skills.length,mastered:0,progress:0};for(const x of skills){const st=prog(x.id).status;if(st==='mastered')r.mastered++;else if(st==='progress')r.progress++}r.todo=r.count-r.mastered-r.progress;return r}
function nextSteps(branchId,limit=5){const rank={progress:0,todo:1};return activeSkills().filter(s=>s.branchId===branchId&&!prog(s.id).mastered&&Core.isReady(D,s.id)).sort((a,b)=>rank[prog(a.id).status]-rank[prog(b.id).status]||a.stage-b.stage).slice(0,limit)}
function shell(){
 const nav=[['home','house','Моя мастерская'],['map','map','Карта навыков'],['projects','flag','Проекты'],['journal','book','Журнал опыта'],['tools','tools','Инструменты'],['mentor','spark','ИИ-наставник'],['data','compass','Правила и данные']];
 $('#app').innerHTML=`<div class="app"><aside class="side"><a class="brand" href="#home" data-action="nav" data-id="home"><div class="brandmark">${ico('layers')}</div><div><b>Своя<br>мастерская</b><span>SKILL RPG · ЛИЧНЫЙ ПУТЬ</span></div></a><nav class="nav" aria-label="Основная навигация">${nav.map(([id,i,t])=>`<button data-action="nav" data-id="${id}" id="nav-${id}">${ico(i)}${t}</button>`).join('')}</nav><div class="side-bottom"><span class="online-dot"></span>Для себя. Своими руками.<p>Опыт подтверждается делами.<br>Карта не выдаёт квалификацию.<br>Нет дедлайнов и штрафов за паузы.</p></div></aside><main class="main"><header class="topbar"><div class="crumb" id="crumb"></div><div class="top-actions"><span id="save-indicator" class="save-indicator"></span>${btn('JSON','export','','export-top','download')}${btn('','theme','','icon-only','moon')}${btn('Записать опыт','new-event','','primary','plus')}</div></header><div id="savewarning"></div><div id="content"></div><div class="footer-note" id="footer-save-note">Свой темп · сохранение на сервере и в Git · резервные копии в разделе «Данные»</div></main></div>`;
 $('[data-action=theme]').setAttribute('aria-label','Переключить светлую и тёмную тему');
}
function render(){
 const focus=document.activeElement?.id;let pos=null;try{pos=document.activeElement.selectionStart}catch{}
 document.documentElement.dataset.theme=D.settings.theme;
 $$('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.id===U.page));
 const names={home:'Мастерская / Личный путь',map:'Навыки / '+(U.branch?getBranch(U.branch)?.title:'Все направления'),projects:'Проекты / От идеи до результата',journal:'Журнал / Только подтверждённый опыт',tools:'Инструменты / Возможности, не список покупок',mentor:'ИИ-наставник / Сначала предложение, потом решение',data:'Система / Правила, резервные копии, источники'};
 $('#crumb').textContent=names[U.page];$('#savewarning').innerHTML=saveError?`<div class="savewarn">${esc(saveError)}</div>`:'';
 const pages={home:homePage,map:mapPage,projects:projectsPage,journal:journalPage,tools:toolsPage,mentor:mentorPage,data:dataPage};
 $('#content').innerHTML=pages[U.page]();
 if(focus){const f=document.getElementById(focus);if(f){f.focus({preventScroll:true});try{if(pos!==null)f.setSelectionRange(pos,pos)}catch{}}}
 updateSaveBadge();
}
function go(page,extra={}){closeModal();Object.assign(U,{page,search:'',status:'all',group:'all'},extra);render();window.scrollTo({top:0,behavior:'instant'})}
function heroArt(){return`<div class="hero-art"><svg viewBox="0 0 310 220" aria-hidden="true"><g fill="none" stroke="#9daf8f" stroke-width="1"><path d="M40 190h236M58 199h186M115 134l-32 20 85 38 81-51-82-33Z"/><path d="m83 154 2 28m83 10v20m81-71v25"/><path d="M165 132V52M165 74l-64-27m64 42 66-39M165 111l-85 4m85 0 88-9" stroke-dasharray="3 4"/></g><g fill="#f4f3e5" stroke="#78906c" stroke-width="1.4"><path d="m80 104 20 10-20 12-20-12Zm-20 10v16l20 12 20-12v-16m-20 12v16"/><path d="m231 31 18 10v20l-18 10-18-10V41Zm0 20v20m-18-30 18 10 18-10"/><path d="m165 27 20 11-20 12-20-12Zm-20 11v22l20 12 20-12V38m-20 12v22"/></g><g stroke="#769061" fill="#c2d0a9"><circle cx="102" cy="46" r="18"/><path d="M102 33v26M90 46h25"/></g><g stroke="#b99b5e" fill="#e2d3a5"><circle cx="253" cy="106" r="20"/><path d="m245 106 5 5 12-13" fill="none" stroke-width="2"/></g><g stroke="#748865" fill="#afc19b"><path d="m147 118 21-12 19 11v27l-19 12-21-12Zm0 0 21 12 19-13m-19 13v26"/></g><circle cx="166" cy="17" r="2" fill="#b99b5e"/><circle cx="58" cy="59" r="2" fill="#b99b5e"/><circle cx="267" cy="174" r="2" fill="#b99b5e"/></svg><span class="caption">ОДИН ПРОЕКТ · НЕСКОЛЬКО ВЕТОК</span></div>`}
function branchCard(b){const s=Core.branchStats(D,b.id);return`<button class="branch-card" style="--bcolor:${esc(b.color)}" data-action="branch" data-id="${esc(b.id)}"><div class="branch-top"><div class="branch-icon">${ico(b.icon)}</div>${D.focus.includes(b.id)?tag('В фокусе','gold'):tag(b.group)}</div><h3>${esc(b.title)}</h3><p>${esc(b.subtitle)}</p><div class="branch-bottom"><span>${s.mastered?'Освоено '+s.mastered+' из '+s.count:s.progress?'В процессе '+s.progress+' из '+s.count:s.count+' '+skillWord(s.count)+' · путь впереди'}</span><span>${s.total?s.total+' XP':'↗'}</span></div>${masteryBar(s)}</button>`}
function questCard(p,n=null){const ps=Core.projectState(D,p.id);return`<article class="panel tight quest-card"><div class="row between">${tag(p.kind==='theory'?'Изучение':'Практический проект',p.kind==='theory'?'blue':'green')}${ps==='done'?tag('✓ Завершён','green'):ps!=='catalog'?tag(PS[ps],'gold'):tag('Шаг '+p.stage)}</div><h3><button class="linkbutton" data-action="project" data-id="${esc(p.id)}">${esc(p.title)}</button></h3><div class="desc">${esc(p.description)}</div><div class="row">${p.branchIds.slice(0,3).map(bTag).join('')}</div><div class="foot"><span class="small muted">${p.skillIds.length} ${skillWord(p.skillIds.length)} · ${esc(p.size)}</span>${btn('Открыть','project',p.id,'sm','arrow')}</div></article>`}
function eventLine(e,full=false){const total=e.allocations.reduce((a,b)=>a+b.points,0);return`<div class="eventline"><div class="eventdot">${e.kind==='practice'?'✓':e.kind==='theory'?'Т':e.kind==='attempt'?'↗':'↺'}</div><div><h4><button class="linkbutton" data-action="event" data-id="${esc(e.id)}">${esc(e.title)}</button></h4><div class="small">${esc(KIND[e.kind])}${e.stale?' · освежить':''} · ${e.allocations.length} ${skillWord(e.allocations.length)}</div>${full?`<p class="small">${esc(e.description)}</p><div class="small">${esc(fmtDate(e.date))}</div>`:''}</div><div class="eventxp ${e.kind==='theory'?'theory-text':''}">+${total} XP</div></div>`}
function homePage(){const s=Core.stats(D);const suggested=['q-shelf','q-fusion','q-resinplan'].map(getProject).filter(p=>p&&!p.archived&&Core.projectState(D,p.id)!=='done');const inwork=activeProjects().filter(p=>['active','planned','paused'].includes(Core.projectState(D,p.id)));return`
<section class="hero"><div><div class="eyebrow">ЛИЧНЫЙ МАРШРУТ · БЕЗ ГОНКИ ЗА ПРОФЕССИЕЙ</div><h1>Не всё уметь.<br>А всё увереннее делать.</h1><p>Душ работает. Бачок починен. Это уже начало. Теперь у каждого нового дела будет своё место на карте — и понятный следующий шаг.</p><div class="row">${btn('Выбрать следующий проект','nav','projects','','arrow')}${tag('Начальный профиль заполнен','green')}</div></div>${heroArt()}</section>
<section class="metrics"><div class="metric"><div class="metric-value">${s.completed}</div><div class="metric-label">завершённых практических проектов</div></div><div class="metric"><div class="metric-value">${s.practice} <span>XP</span></div><div class="metric-label">завершённая практика · отдельно</div></div><div class="metric"><div class="metric-value">${s.theory} <span>XP</span></div><div class="metric-label">теория · не заменяет работу руками</div></div><div class="metric"><div class="metric-value">${s.mastered} <span>/ ${s.skills}</span></div><div class="metric-label">навыков освоено · знакомство с ${s.explored}</div></div></section>
<div class="section-head"><div><h2>Твои направления в фокусе</h2><p>Фокус помогает выбирать, но не закрывает остальные ветки.</p></div>${btn('Вся карта','nav','map','text','arrow')}</div><div class="cards">${D.focus.map(getBranch).filter(Boolean).map(branchCard).join('')||'<div class="empty">Добавь направление в фокус на его странице.</div>'}</div>
<div class="section-head"><div><h2>${inwork.length?'На твоём верстаке':'Три возможных следующих шага'}</h2><p>${inwork.length?'Этапы можно отмечать. Опыт появится только после завершения.':'Это предложения, не назначенные задачи. Начинай с того, что сейчас радует.'}</p></div></div><div class="cards">${(inwork.length?inwork:suggested).slice(0,3).map(questCard).join('')}</div>
<div class="split" style="margin-top:25px"><section class="panel"><div class="row between"><h3>Уже сделано</h3>${btn('Журнал','nav','journal','text sm')}</div><div class="timeline">${D.events.filter(x=>x.kind==='practice'||x.kind==='theory').slice(-5).reverse().map(e=>eventLine(e)).join('')}</div></section><section class="panel"><div class="eyebrow">ЧЕСТНАЯ ИГРА</div><h3 style="margin-top:12px">Засчитываем результат,<br>а не намерение</h3><p class="muted" style="font-size:13px;line-height:1.8">Пока дело продолжается — оно на верстаке, без XP. Прекращённую попытку можно записать отдельно. Старый опыт не обнуляется, а помечается «освежить».</p><div class="hr"></div><p class="annotation">${s.historical} XP прошлого опыта и ${s.attempt} XP прекращённых попыток хранятся отдельно. Числа — игровая договорённость, не оценка квалификации.</p>${btn('Как считается опыт','nav','data','text sm','arrow')}</section></div>
<div class="section-head"><h2>Маленькие вехи</h2></div><div class="badge-list">${milestones().map(x=>`<div class="badge ${x.ok?'':'locked'}"><b>${x.ok?'✦':'◇'} ${x.title}</b><span>${x.desc}</span></div>`).join('')}</div>`}
function closedModules(){const by={};for(const s of activeSkills())(by[s.branchId+'\u0000'+s.module]||=[]).push(s);return Object.values(by).filter(list=>list.every(s=>prog(s.id).mastered)).length}
function milestones(){const st=Core.stats(D);return[{title:'Первая галочка',desc:'Отмечен первый освоенный навык',ok:st.mastered>0},{title:'Закрытая подветка',desc:'Все навыки одной подветки освоены',ok:closedModules()>0},{title:'Экватор ветки',desc:'Освоена половина навыков направления',ok:activeBranches().some(b=>{const x=Core.branchStats(D,b.id);return x.count&&x.mastered*2>=x.count})},{title:'Первый результат',desc:'Есть завершённая работа',ok:st.completed>0},{title:'Не сдались на демонтаже',desc:'Подтверждён опыт сложной разборки',ok:Core.skillStats(D,'base.stuck').total>0},{title:'Широкий кругозор',desc:'Есть опыт в четырёх направлениях',ok:activeBranches().filter(b=>Core.branchStats(D,b.id).seen>0).length>=4},{title:'Первая мебель',desc:'Завершён один мебельный проект',ok:['q-shelf','q-bench','q-table','q-bed'].some(id=>Core.projectState(D,id)==='done')},{title:'Первый композит',desc:'Подтверждён свой образец',ok:Core.skillStats(D,'composite.layup').practice>0}]}
function branchOptions(selected,all=true){return(all?'<option value="all">Все направления</option>':'')+activeBranches().map(b=>`<option value="${esc(b.id)}" ${b.id===selected?'selected':''}>${esc(b.title)}</option>`).join('')}
function searchableSkill(s){return Core.norm([s.title,s.module,s.goal,s.exercise,getBranch(s.branchId)?.title,...s.toolIds.map(id=>getTool(id)?.title||id)].join(' '))}
function skillRow(s){const n=Core.skillStats(D,s.id),g=prog(s.id);const ready=g.status==='todo'&&Core.isReady(D,s.id)&&s.prerequisites.length;return`<div class="skill-row ${g.status}"><button class="skill-tick ${g.status}" data-action="toggle-mastered" data-id="${esc(s.id)}" aria-pressed="${g.mastered}" aria-label="${g.mastered?'Снять отметку освоения':'Отметить освоенным'}: ${esc(s.title)}" title="${g.mastered?'Освоен '+esc(fmtDate(g.date)):'Отметить освоенным'}">${g.mastered?ico('check'):g.checks?`<small>${g.checks}/${g.criteria}</small>`:''}</button><button class="skill-open" data-action="skill" data-id="${esc(s.id)}"><div><h4>${esc(s.title)}</h4><p>${g.mastered?'Освоен':g.criteria?(g.checks?'Критерии '+g.checks+' из '+g.criteria:g.criteria+' '+critWord(g.criteria)+' освоения'):esc(STAGE[s.stage])}${ready?' · предпосылки закрыты':''}${n.stale?' · освежить прошлый опыт':''}${s.risk==='pro'?' · обучение / специалист':''}</p></div><span class="skill-points"><span class="xp-kind ${n.practice||n.historical?'seen':n.theory?'theory':''}">${n.total?n.total+' XP':'—'}</span>${D.goals[s.id]?'<br>цель':''}</span></button></div>`}
const critWord=n=>(n%100>=11&&n%100<=14)?'критериев':n%10===1?'критерий':n%10>=2&&n%10<=4?'критерия':'критериев';
function mapPage(){if(U.branch)return branchPage(getBranch(U.branch));const q=Core.norm(U.search);let bs=activeBranches().filter(b=>(U.group==='all'||b.group===U.group)&&(U.status!=='focus'||D.focus.includes(b.id))&&(U.status!=='seen'||Core.branchStats(D,b.id).seen>0));if(q)bs=bs.filter(b=>Core.norm(b.title+' '+b.subtitle).includes(q)||activeSkills().some(s=>s.branchId===b.id&&searchableSkill(s).includes(q)));
return`<div class="pagehead"><div><div class="eyebrow">${activeBranches().length} НАПРАВЛЕНИЙ · ${activeSkills().length} НАВЫКА</div><h1 style="margin-top:8px">Карта возможностей</h1><p>Техника изучается в одном месте. Один проект связывает несколько навыков — без размножения одинаковых узлов.</p></div>${btn('Добавить направление','new-branch','','','plus')}</div><div class="filters"><input type="search" id="map-search" placeholder="Фрезер, Arduino, стеклопластик, мультитул…" value="${esc(U.search)}"><select id="map-group">${['all','Фундамент','Материалы','Системы','Применение'].map(x=>`<option value="${x}" ${x===U.group?'selected':''}>${x==='all'?'Все группы':x}</option>`).join('')}</select><select id="map-status"><option value="all">Все направления</option><option value="focus" ${U.status==='focus'?'selected':''}>В моём фокусе</option><option value="seen" ${U.status==='seen'?'selected':''}>Есть опыт</option></select></div><div class="cards">${bs.map(branchCard).join('')||'<div class="empty">Ничего не найдено. Попробуй более короткое слово.</div>'}</div>${q?`<div class="section-head"><h2>Подходящие навыки</h2><span class="small muted">По названию, цели и инструментам</span></div><div class="panel">${activeSkills().filter(s=>bs.some(b=>b.id===s.branchId)&&searchableSkill(s).includes(q)).map(skillRow).join('')||'<p class="muted">Совпадение найдено в названии направления.</p>'}</div>`:''}<div class="notice" style="margin-top:22px"><b>А где осциллирующий мультитул?</b><p>В «Основе мастерской → Резка и демонтаж». Инструмент обслуживает несколько веток, но владение им не превращается в пять разных навыков. ${btn('Посмотреть','skill','base.multitool','text sm')}</p></div>`}
function branchPage(b){if(!b)return'<div class="empty">Направление не найдено.</div>';const q=Core.norm(U.search);const all=activeSkills().filter(s=>s.branchId===b.id);const pass=s=>{const st=prog(s.id).status;return U.mfilter==='all'||(U.mfilter==='left'?st!=='mastered':st===U.mfilter)};const skills=all.filter(s=>(!q||searchableSkill(s).includes(q))&&pass(s));const modules=[...new Set(all.map(s=>s.module))];const st=Core.branchStats(D,b.id);const quests=activeProjects().filter(p=>p.branchIds.includes(b.id)).sort((a,c)=>a.stage-c.stage);const next=nextSteps(b.id);const pct=st.count?Math.round(100*st.mastered/st.count):0;
const pills=[['all','Все',st.count],['left','Осталось',st.count-st.mastered],['progress','В процессе',st.progress],['mastered','Освоено',st.mastered]];
return`
<div class="row between" style="margin-bottom:18px">${btn('Вся карта','all-branches','','text','back')}<div class="row">${btn(D.focus.includes(b.id)?'★ В фокусе':'☆ В фокус','focus',b.id,'sm')}${btn('Редактировать','edit-branch',b.id,'sm','edit')}</div></div><section class="panel branch-header" style="--bcolor:${esc(b.color)}"><div><div class="row">${tag(b.group)}${st.seen?tag('Опыт в '+st.seen+' из '+st.count,'blue'):''}${st.total?tag(st.total+' XP'):''}</div><h1>${esc(b.title)}</h1><p class="muted">${esc(b.goal)}</p><div class="mastery-summary"><div class="mastery-count"><b>${st.mastered}</b><span>из ${st.count} ${skillWord(st.count)} освоено · ${pct}%</span></div>${masteryBar(st,'big')}<div class="mastery-legend"><span><i class="m-done"></i>Освоено ${st.mastered}</span><span><i class="m-prog"></i>В процессе ${st.progress}</span><span><i></i>Впереди ${st.todo}</span></div></div></div><div class="stack">${btn('Проработать с ИИ','ai-branch',b.id,'primary','spark')}${btn('Добавить навык','new-skill',b.id,'','plus')}</div></section>
<div class="filters"><input id="branch-search" type="search" value="${esc(U.search)}" placeholder="Поиск внутри направления"><div class="pills" role="group" aria-label="Показать навыки">${pills.map(([k,t,n])=>`<button class="pill ${U.mfilter===k?'active':''}" data-action="mfilter" data-id="${k}" aria-pressed="${U.mfilter===k}">${t} <span>${n}</span></button>`).join('')}</div></div><div class="split"><div>${modules.map((m,i)=>{const list=skills.filter(s=>s.module===m);if(!list.length)return'';const g=groupStats(all.filter(s=>s.module===m)),closed=g.mastered===g.count;return`<section class="module ${closed?'closed':''}"><h3 class="module-title"><span class="module-no">${closed?'✓':String(i+1).padStart(2,'0')}</span><span class="module-name">${esc(m)}</span><span class="module-count">${closed?'закрыто':g.mastered+' / '+g.count}</span></h3>${masteryBar(g,'thin')}${list.map(skillRow).join('')}</section>`}).join('')||`<div class="empty">${U.mfilter==='left'&&st.count?'Всё направление освоено. Можно углубить его с ИИ или добавить свой навык.':'Под этот фильтр навыков нет.'}</div>`}</div><aside class="stack"><section class="panel tight"><div class="eyebrow">СЛЕДУЮЩИЕ ШАГИ</div><h3 style="margin-top:9px">${next.length?'Можно браться сейчас':'Шаги не найдены'}</h3><p class="small muted">${next.length?'Не освоены, а все их предпосылки уже закрыты. Сначала — начатое.':st.count&&st.mastered===st.count?'Всё направление отмечено освоенным.':'У оставшихся навыков есть неосвоенные предпосылки — начни с них.'}</p>${next.map(s=>{const g=prog(s.id);return`<div class="route-line"><span class="route-number ${g.status}">${g.status==='progress'?'◐':'○'}</span><div><h4><button class="linkbutton" data-action="skill" data-id="${esc(s.id)}">${esc(s.title)}</button></h4><p>${esc(s.module)}${g.checks?' · '+g.checks+' из '+g.criteria:''}</p></div></div>`}).join('')}</section><section class="panel tight"><div class="eyebrow">МАРШРУТ ЧЕРЕЗ РЕАЛЬНЫЕ ДЕЛА</div><h3 style="margin-top:9px">Проекты направления</h3><p class="small muted">Порядок рекомендательный. Это не обязательные уровни и не допуск к опасной работе.</p>${quests.slice(0,9).map((p,i)=>`<div class="route-line"><span class="route-number">${Core.projectState(D,p.id)==='done'?'✓':i+1}</span><div><h4><button class="linkbutton" data-action="project" data-id="${esc(p.id)}">${esc(p.title)}</button></h4><p>${esc(STAGE[p.stage])} · ${esc(p.kind==='theory'?'изучение':'практика')}</p></div></div>`).join('')||'<p class="muted small">Добавь проект сам или попроси ИИ предложить маршрут.</p>'}${btn('Все проекты ветки','branch-projects',b.id,'text sm','arrow')}</section><section class="notice"><b>Галочка — твоё решение</b><p>«Освоен» ставишь ты, когда уверенно проходишь критерии. XP (${st.total}) отдельно показывает подтверждённые дела. Ни то, ни другое не заменяет обучения там, где нужен специалист.</p></section></aside></div>`}
function projectsPage(){const q=Core.norm(U.search);let ps=activeProjects().filter(p=>(U.projectBranch==='all'||p.branchIds.includes(U.projectBranch))&&(!q||Core.norm(p.title+' '+p.description).includes(q))&&(U.status==='all'||Core.projectState(D,p.id)===U.status)&&(!U.simple||(p.stage<=2&&p.risk!=='pro')));return`<div class="pagehead"><div><div class="eyebrow">КВЕСТЫ, КОТОРЫЕ ОСТАЮТСЯ В ДОМЕ</div><h1 style="margin-top:8px">Изучать через дела</h1><p>Этапы и критерии помогут довести работу до результата. Чекбоксы не начисляют опыт — завершение подтверждаешь ты.</p></div>${btn('Свой проект','new-project','','','plus')}</div><div class="filters"><input type="search" id="project-search" value="${esc(U.search)}" placeholder="Найти полку, образец, датчик…"><select id="project-branch">${branchOptions(U.projectBranch)}</select><select id="project-status"><option value="all">Все состояния</option>${Object.entries(PS).map(([id,t])=>`<option value="${id}" ${id===U.status?'selected':''}>${t}</option>`).join('')}</select></div><div class="row between" style="margin-bottom:16px"><span class="small muted">${ps.length} проектов</span><label class="checkline"><input type="checkbox" id="project-simple" ${U.simple?'checked':''}><span>Небольшие первые шаги, без профессиональных операций</span></label></div><div class="cards">${ps.map(questCard).join('')||'<div class="empty">Нет проектов под выбранным фильтром.</div>'}</div><div class="notice warn" style="margin-top:22px"><b>Карточка проекта — это каркас изучения, не готовая техническая инструкция.</b><p>Размеры, нагрузки, совместимость и порядок опасных операций проверяются отдельно под реальную задачу. Квесты с меткой «Обучение / специалист» предполагают соответствующую подготовку.</p></div>`}
function journalPage(){const st=Core.stats(D),q=Core.norm(U.search);const es=D.events.filter(e=>(U.journalKind==='all'||e.kind===U.journalKind)&&(!q||Core.norm(e.title+' '+e.description).includes(q))).slice().reverse();return`<div class="pagehead"><div><div class="eyebrow">ИСТОРИЯ, А НЕ САМОСТОЯТЕЛЬНО НАРИСОВАННЫЕ УРОВНИ</div><h1 style="margin-top:8px">Журнал опыта</h1><p>Любая цифра ведёт к конкретной записи: что ты сделал, на каком основании и какие навыки затронул.</p></div>${btn('Новая запись','new-event','','primary','plus')}</div><div class="metrics">${Object.keys(KIND).map(k=>`<div class="metric"><div class="metric-value">${st[k]} <span>XP</span></div><div class="metric-label">${KIND[k]}</div></div>`).join('')}</div><div class="filters"><input type="search" id="journal-search" value="${esc(U.search)}" placeholder="Найти запись"><select id="journal-kind"><option value="all">Все виды опыта</option>${Object.entries(KIND).map(([k,t])=>`<option value="${k}" ${U.journalKind===k?'selected':''}>${t}</option>`).join('')}</select></div><section class="panel"><div class="timeline">${es.map(e=>eventLine(e,true)).join('')||'<div class="empty">Пока нет таких записей. Планы здесь не отображаются.</div>'}</div></section><div class="annotation" style="margin-top:13px">Начальные записи подтверждены твоими словами. Точные даты ремонта не назначены задним числом. Незавершённые и неподтверждённые работы в начальный профиль не добавлены.</div>`}
function toolsPage(){const q=Core.norm(U.search);const used=new Set(D.events.flatMap(e=>e.toolIds||[]));const sf=U.toolStatus||'all';const tools=D.tools.filter(t=>(!q||Core.norm(t.title+' '+t.es+' '+t.description).includes(q))&&(U.toolBranch==='all'||t.branchIds.includes(U.toolBranch))&&(sf==='all'||(D.inventory[t.id]||(used.has(t.id)?'used':'unknown'))===sf));const haveCount=D.tools.filter(t=>(D.inventory[t.id]||(used.has(t.id)?'used':'unknown'))==='have').length;const wantCount=D.tools.filter(t=>(D.inventory[t.id]||(used.has(t.id)?'used':'unknown'))==='want').length;const borrowCount=D.tools.filter(t=>(D.inventory[t.id]||(used.has(t.id)?'used':'unknown'))==='borrow').length;const usedCount=D.tools.filter(t=>(D.inventory[t.id]||(used.has(t.id)?'used':'unknown'))==='used').length;const pills=[['all','Все',D.tools.length],['have','Есть у меня',haveCount],['want','Хочу под задачу',wantCount],['borrow','Одолжить',borrowCount],['used','Пользовался',usedCount]];return`<div class="pagehead"><div><div class="eyebrow">${haveCount} ИЗ ${D.tools.length} ИНСТРУМЕНТОВ В НАЛИЧИИ</div><h1 style="margin-top:8px">Твой набор возможностей</h1><p>Отмечай то, что уже есть в мастерской — даже самые простые мелочи и расходники. Владение и планы отмечаются отдельно; покупка сама по себе не даёт XP.</p></div>${btn('Добавить инструмент','new-tool','','primary','plus')}</div><div class="filters"><input type="search" id="tool-search" value="${esc(U.search)}" placeholder="Название по-русски или по-испански"><select id="tool-branch">${branchOptions(U.toolBranch)}</select><select id="tool-status"><option value="all">Любой статус</option>${toolStatuses().map(([k,t])=>`<option value="${k}" ${k===sf?'selected':''}>${t}</option>`).join('')}</select></div><div class="pills" role="group" aria-label="Фильтр по статусу инструмента">${pills.map(([k,t,n])=>`<button class="pill ${sf===k?'active':''}" data-action="tool-status-pill" data-id="${k}" aria-pressed="${sf===k}">${t} <span>${n}</span></button>`).join('')}</div><div class="cards">${tools.map(t=>{const v=D.inventory[t.id]||(used.has(t.id)?'used':'unknown');const isHave=v==='have';return`<article class="panel tool-card ${isHave?'have':''}"><div class="row between">${ico(t.id==='multitool'?'spark':'tools')}${isHave?tag('✓ Есть у меня','green'):(v==='want'?tag('★ Хочу','gold'):(v==='borrow'?tag('Одолжить','blue'):tag(t.branchIds.length+' направл.')))}</div><h3>${esc(t.title)}</h3><div class="es">${esc(t.es)}</div><p>${esc(t.description)}</p><div class="row">${t.branchIds.slice(0,3).map(bTag).join('')}</div><div class="row between" style="margin-top:auto;gap:8px"><button class="btn sm ${isHave?'green':''}" data-action="toggle-tool-have" data-id="${esc(t.id)}" title="${isHave?'Снять отметку наличия':'Отметить: есть у меня'}">${isHave?ico('check')+'Есть у меня':ico('plus')+'Отметить: есть'}</button><select aria-label="Статус: ${esc(t.title)}" data-inventory="${esc(t.id)}" style="flex:1;min-width:125px;min-height:34px;padding:4px 8px;font-size:12px">${toolStatuses().map(([k,n])=>`<option value="${k}" ${v===k?'selected':''}>${n}</option>`).join('')}</select></div><div class="row between" style="margin-top:4px">${btn('Связанные навыки','tool-skills',t.id,'text sm','arrow')}${btn('Изменить','edit-tool',t.id,'text sm','edit')}</div></article>`}).join('')||'<div class="empty">Инструменты не найдены. Можно добавить новый инструмент кнопкой вверху.</div>'}</div>`}
function toolStatuses(){return[['unknown','Наличие не указано'],['used','Пользовался · наличие неизвестно'],['borrow','Могу одолжить / арендовать'],['have','Есть у меня'],['want','Хочу под задачу'],['skip','Пока не нужен']]}
function mentorPage(){const h=U.health;let status=location.protocol==='file:'?'Открыт автономный HTML. Доступен ручной обмен с чатом.':!h?'Локальное подключение ещё не проверено.':h.accessRequired&&!h.accessGranted?'Сервер доступен, но ИИ закрыт ключом доступа.':h.configured?'API настроен на сервере · '+h.model:'Локальный сервер работает; API-ключ ещё не настроен.';return`
<div class="pagehead"><div><div class="eyebrow">НАСТАВНИК И РЕДАКТОР КАРТЫ</div><h1 style="margin-top:8px">Расскажи о деле.<br>Или вырасти новую ветку.</h1><p>ИИ может предложить опыт, новые навыки, проекты и уточнения существующих карточек. Самостоятельно ничего не меняет.</p></div></div>
<div class="ai-layout"><section class="panel"><div class="field"><label for="ai-mode">Что делаем</label><select id="ai-mode"><option value="experience" ${U.mode==='experience'?'selected':''}>Разобрать завершённую работу или изученный материал</option><option value="expand" ${U.mode==='expand'?'selected':''}>Углубить / изменить наполнение направления</option><option value="plan" ${U.mode==='plan'?'selected':''}>Предложить реальные проекты и последовательность</option></select></div><div class="field"><label for="ai-scope">Направление для подробного контекста</label><select id="ai-scope">${branchOptions(U.aiScope,true)}</select></div><div class="field"><label for="ai-text">Твой запрос</label><textarea id="ai-text" class="ai-prompt" placeholder="Например: проработай дерево подробнее под простую мебель. Хочу 5 конкретных проектов от полки до кровати, критерии результата и связи с существующими навыками. Не начисляй опыт за планы.">${esc(U.aiText)}</textarea></div><div class="ai-examples"><button class="ai-example" data-action="ai-example" data-id="wood">Больше конкретики в дереве</button><button class="ai-example" data-action="ai-example" data-id="composite">Первые шаги в стеклопластике</button><button class="ai-example" data-action="ai-example" data-id="experience">Разобрать мою завершённую работу</button></div>
<div class="notice"><div class="status-line"><span class="status-light ${h?.configured?'ok':''}"></span>${esc(status)}</div><p>Ключ OpenAI никогда не вводится в игру. Сервер получает его из переменной окружения или локального .env.</p>${h?.accessRequired?`<div class="field" style="margin-top:12px"><label for="ai-access-key">Ключ доступа к этому серверу · WORKSHOP_ACCESS_KEY</label><div class="row"><input id="ai-access-key" type="password" autocomplete="off" placeholder="${h.accessGranted?'Ключ принят':'Вставь ключ из .env сервера'}" style="flex:1">${btn('Сохранить','save-access-key','','sm')}</div><p class="annotation">Хранится только в этом браузере и не попадает в экспорт JSON.</p></div>`:''}</div>
<label class="checkline" style="margin:17px 0"><input id="ai-consent" type="checkbox" ${U.aiConsent?'checked':''}><span>Отправить мой запрос, каталог и контекст опыта в OpenAI API. Это отдельный платный API-запрос, не часть подписки ChatGPT.</span></label><div class="row"><button class="btn primary" data-action="ai-request" ${U.aiBusy?'disabled':''}>${U.aiBusy?'<span class="busy"></span> Анализируется':ico('spark')+'Получить предложение через API'}</button>${btn('Проверить сервер','health','','sm')}</div>${U.aiMessage?`<div class="notice ${U.aiMessage.startsWith('Ошибка')?'danger':''}" style="margin-top:14px">${esc(U.aiMessage)}</div>`:''}
<div class="hr"></div><h3>Без API: через этот чат</h3><p class="annotation">Игра соберёт запрос, правила, ID навыков и формат ответа. Передай текст в чат, получи JSON и верни его сюда. Это настоящий ручной обмен данными, не имитация подключённого ИИ.</p><div class="row" style="margin-top:12px">${btn('Подготовить запрос для чата','chat-package','','','book')}${btn('Вставить ответ JSON','paste-proposal','','','plus')}</div>${U.chatPackage?`<div class="notice" style="margin-top:13px"><b>Пакет подготовлен для ревизии ${U.packageRevision}</b><p>До возвращения ответа не меняй карту: устаревшие предложения будут отклонены.</p><div class="row" style="margin-top:9px">${btn('Скопировать','copy-package','','sm')}${btn('Сохранить .txt','download-package','','sm','download')}${btn('Посмотреть','show-package','','text sm')}</div></div>`:''}</section>
<aside class="stack"><section class="panel"><div class="eyebrow">ТВОЁ ОДОБРЕНИЕ — ОБЯЗАТЕЛЬНО</div><h3 style="margin-top:10px">Как меняется карта</h3><div class="route-line"><span class="route-number">1</span><div><h4>Контекст, а не угадывание</h4><p>ИИ получает существующие ID, правила и записи опыта.</p></div></div><div class="route-line"><span class="route-number">2</span><div><h4>Предложение по пунктам</h4><p>Новые карточки и изменения показываются до записи. Можно снять отдельные галочки.</p></div></div><div class="route-line"><span class="route-number">3</span><div><h4>Проверка связей</h4><p>Неизвестные ID, повторные начисления и циклы зависимостей блокируются.</p></div></div><div class="route-line"><span class="route-number">4</span><div><h4>Применить и при необходимости отменить</h4><p>До трёх последних состояний доступны для отмены. JSON — долговременная резервная копия.</p></div></div></section><section class="notice warn"><b>ИИ не видел твою работу</b><p>Его предложение может ошибаться. Проверяй факт завершения, назначение материалов, риски и начисления. Снижение предупреждения о риске через ИИ запрещено.</p></section><section class="panel tight"><h4>Проверить механику без запроса</h4><p class="annotation">Ниже — подготовленный пример добавления карточки, не ответ модели. Он тоже потребует подтверждения.</p>${btn('Посмотреть демо-предложение','demo-proposal','','text sm','arrow')}</section></aside></div>
${U.proposal?proposalView(U.proposal):''}`}
const LABELS={title:'Название',module:'Подветка',goal:'Цель',exercise:'Учебное действие',proof:'Критерий результата',prerequisites:'Предпосылки',toolIds:'Инструменты',risk:'Риск',stage:'Ступень маршрута',branchId:'Направление',description:'Описание',skillIds:'Навыки',steps:'Этапы',checks:'Критерии',branchIds:'Направления',kind:'Вид опыта',size:'Масштаб',allocations:'Предлагаемый опыт',date:'Дата',dateLabel:'Уточнение даты',evidence:'Основание / подтверждение',projectId:'Проект',stale:'Освежить',subtitle:'Подзаголовок',group:'Группа'};
const OPNAMES={add_skill:'Новый навык',update_skill:'Изменить навык',add_project:'Новый проект',update_project:'Изменить проект',add_branch:'Новое направление',update_branch:'Изменить направление',add_event:'Записать опыт',archive_skill:'Убрать навык в архив',archive_project:'Убрать проект в архив'};
function opBefore(op){if(op.type.includes('skill'))return getSkill(op.targetId);if(op.type.includes('project'))return getProject(op.targetId);if(op.type.includes('branch'))return getBranch(op.targetId);return null}
function valueText(k,v){if(k==='allocations')return(v||[]).map(a=>(getSkill(a.skillId)?.title||a.skillId)+' +'+a.points+' XP').join('\n');if(k==='risk')return RISK[v];if(k==='kind')return KIND[v]||v;if(Array.isArray(v))return v.map(x=>typeof x==='string'?(getSkill(x)?.title||getTool(x)?.title||getBranch(x)?.title||x):JSON.stringify(x)).join('\n');if(v===null)return'Не указано';return String(v)}
function proposalView(p){return`<section class="proposal panel" id="proposal-section"><div class="row between"><div><div class="eyebrow">ПРОВЕРЬ ПЕРЕД ПРИМЕНЕНИЕМ</div><h2 style="margin-top:7px">Предложение · ${p.operations.length} изменений</h2></div>${tag('Для ревизии '+p.baseRevision,p.baseRevision===D.revision?'green':'red')}</div><p class="muted" style="font-size:13px">${esc(p.summary)}</p>${p.questions.length?`<div class="notice warn" style="margin-top:15px"><b>Вопросы и неопределённости</b>${p.questions.map(q=>`<p>${esc(q)}</p>`).join('')}</div>`:''}${p.operations.map(op=>{const before=opBefore(op),d=op.data;const keys=Object.keys(d).filter(k=>LABELS[k]&&(!before||JSON.stringify(before[k])!==JSON.stringify(d[k])));return`<article class="proposal-op"><div class="op-head"><input type="checkbox" aria-label="Выбрать изменение: ${esc(d.title||op.targetId)}" data-proposal-op="${esc(op.id)}" ${U.proposalSelected.includes(op.id)?'checked':''}><div class="op-title"><div class="row">${tag(OPNAMES[op.type],op.type==='add_event'?'gold':'green')}${d.risk?riskTag(d.risk):''}</div><h4 style="margin-top:7px">${esc(d.title||before?.title||op.targetId)}</h4></div></div><div class="op-reason">${esc(op.reason)}</div><div class="diff">${op.type.startsWith('archive_')?'<div class="after">Скрыть из активного каталога. Записи опыта и ID сохраняются.</div>':keys.map(k=>`<strong>${esc(LABELS[k])}</strong>${before?`<div class="before">${esc(valueText(k,before[k]))}</div>`:''}<div class="after">${esc(valueText(k,d[k]))}</div>`).join('')}</div></article>`}).join('')||'<div class="notice" style="margin-top:15px">Изменений нет. Возможно, сначала нужно ответить на вопросы выше.</div>'}<div class="row" style="margin-top:15px">${btn('Применить выбранное','apply-proposal','','primary','check')}${btn('Отбросить предложение','discard-proposal','','')}${btn('Полный JSON','proposal-json','','text sm')}</div><p class="annotation">Опыт начисляется только выбранными записями add_event. Добавление навыков и проектов не даёт XP. Выбор части взаимосвязанных изменений может потребовать включить новую зависимость.</p></section>`}
function dataPage(){return`<div class="pagehead"><div><div class="eyebrow">ПРАВИЛА, КОТОРЫЕ МОЖНО ОБСУЖДАТЬ</div><h1 style="margin-top:8px">Твоя игра. Твои данные.</h1><p>Здесь нет обязанности освоить всё. Карта поддерживает любопытство, а журнал сохраняет реальные дела.</p></div>${btn('Экспорт JSON','export','','primary','download')}</div><div class="rule-grid">${[
['01','Практика после завершения','Пока работа продолжается, она хранится как проект в работе: этапы, заметки, без XP. Отметка «всё сделано» открывает запись результата, но не подтверждает его за тебя.'],
['02','Теория остаётся теорией','Полный курс может получить небольшой теоретический зачёт. Из просмотра курса нельзя автоматически сделать вывод, что ты умеешь проводить экстракцию, сварку или монтаж.'],
['03','Старый опыт не обнуляется','Fusion, Arduino, ESP и ручные инструменты уже не ноль. У них есть отдельные исторические записи. Давно не практиковавшееся помечается «освежить», без штрафов за время.'],
['04','Прекращённая попытка — отдельная история','Небольшой зачёт допустим, когда действительно работал, но окончательно остановился. Текущая работа не превращается в попытку только ради начисления.'],
['05','Одна технология — одно место','Например, сварка находится в металле. Автомобильный или строительный проект ссылается на неё, а не создаёт копию навыка. Изменить структуру можно, сохраняя ID и историю.'],
['06','Ни XP, ни ИИ не выдают допуск','Опасные процессы отмечены отдельно. Теория, наблюдение и обучение здесь полезны, но самостоятельный газовый, сетевой, высотный или несущий монтаж не открывается накоплением очков.'],
['07','«Освоен» — твоя галочка','У каждого навыка есть проверяемые критерии: «Отличаю…», «Сделал…», «Могу…». Отмечай их по мере уверенности и закрывай навык, когда он действительно твой. Галочки не дают XP и не требуют их: опыт и освоение считаются отдельно.']
].map(([n,t,d])=>`<article class="panel"><div class="rule-number">${n}</div><h3>${t}</h3><p>${d}</p></article>`).join('')}</div>
<section class="panel" style="margin-top:20px"><h2>Как устроены очки</h2><p class="annotation">Это первоначальная игровая шкала, а не измерение компетентности. Крупная цифра сама по себе ничего не удостоверяет. Количество разных навыков с опытом показывает широту, а не процент мастерства.</p><div class="cards four" style="margin-top:16px">${Object.entries(Core.CAPS).map(([k,n])=>`<div class="detail-box"><h4>${KIND[k]}</h4><p>До <b>${n} XP</b> за запись</p></div>`).join('')}</div><p class="annotation">В одной записи на один навык — 1–30 XP, но действует и общий предел вида опыта. Обычное маленькое действие можно оценить в 3–10, сложную новую практику — в 10–25. Начальные значения условны и доступны для редактирования. Нет отдельных бонусов за проект сверх его же распределения по навыкам — двойной счёт исключён.</p></section>
<section class="panel" style="margin-top:20px"><div class="row between"><div><div class="eyebrow">НАДЁЖНОЕ ХРАНЕНИЕ</div><h2>Хранилище на сервере и Git</h2></div><div class="row">${btn('Обновить статус','refresh-backups','','sm')}${btn('Сохранить сейчас','server-save-now','','sm primary','save')}${btn('Создать резервную копию','server-backup-now','','sm','plus')}${btn('Коммит в Git…','server-git-commit','','sm','flag')}</div></div><p class="annotation" style="margin-top:8px">Прогресс не привязан к браузеру: при работе через локальный сервер (<code>python3 server.py</code>) состояние пишется в <code>data/save.json</code>, снимки складываются в <code>data/backups/</code>, и создаётся коммит в Git.</p><div class="cards" style="margin-top:16px"><div class="detail-box"><h4>Файл сохранения</h4><p><b>data/save.json</b><br><span class="small muted">Ревизия: <b>r${D.revision}</b>${U.serverLastSaved?` · ${new Date(U.serverLastSaved).toLocaleTimeString('ru-RU')}`:''}</span></p></div><div class="detail-box"><h4>Git-репозиторий</h4><p><b>${U.serverGit?.available?`Ветка: ${esc(U.serverGit.branch||'master')}`:'Не обнаружен'}</b><br><span class="small muted">${U.serverGit?.lastCommit?esc(U.serverGit.lastCommit):'Коммитов пока нет'}</span></p></div><div class="detail-box"><h4>Резервные копии</h4><p><b>${U.serverBackups?.length||0} снимков</b><br><span class="small muted">В папке data/backups/</span></p></div></div>${(U.serverBackups&&U.serverBackups.length)?`<div class="section-head" style="margin-top:20px"><h3>Резервные копии на сервере</h3></div><div style="overflow-x:auto"><table class="backup-table"><thead><tr><th>Файл копии</th><th>Время снимка</th><th>Ревизия</th><th>Размер</th><th>Действие</th></tr></thead><tbody>${U.serverBackups.slice(0,12).map(b=>`<tr><td><code>${esc(b.filename)}</code></td><td>${esc(new Date(b.mtime).toLocaleString('ru-RU'))}</td><td><b>${b.revision!==null?'r'+b.revision:'—'}</b></td><td>${Math.round(b.size/1024)} КБ</td><td>${btn('Восстановить','server-restore-backup',b.filename,'sm danger')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="annotation" style="margin-top:12px">Снимки резервных копий сохраняются на диск при каждом изменении и доступны для быстрого восстановления.</p>'}</section>
<div class="split" style="margin-top:20px"><section class="panel"><h2>Резервные копии и отмена</h2><div class="data-row"><span>Ревизия состояния</span><b>${D.revision}</b></div><div class="data-row"><span>Направления / навыки / проекты</span><b>${D.branches.length} / ${D.skills.length} / ${D.projects.length}</b></div><div class="data-row"><span>Освоено навыков</span><b>${Core.stats(D).mastered}</b></div><div class="data-row"><span>Выгрузить всю игру с прогрессом</span>${btn('Экспорт JSON','export','','sm')}</div><div class="data-row"><span>Восстановить из копии</span>${btn('Импорт JSON','import-state','','sm')}</div><div class="data-row"><span>Вернуться на одно изменение</span><button class="btn sm" data-action="undo" ${undo.length?'':'disabled'}>${ico('undo')}Отменить (${undo.length})</button></div>${hasOldSave()?`<div class="data-row"><span>Сохранение до обновления на v${Core.VERSION}</span>${btn('Выгрузить','old-save','','sm','download')}</div>`:''}${corruptBackup?`<div class="data-row"><span>Непрочитанное исходное сохранение</span>${btn('Выгрузить исходник','corrupt-backup','','sm')}</div>`:''}<div class="data-row"><span>Стартовый профиль</span>${btn('Сбросить…','reset','','sm danger')}</div><p class="annotation">В автономном режиме без сервера данные сохраняются в localStorage браузера. При запущенном server.py ведущим хранилищем является data/save.json на сервере. Экспорт JSON позволяет перенести файл в любую другую систему.</p></section><section class="panel"><h2>Подключение ИИ</h2><p class="annotation">Автономный HTML полностью работает без сервера. Через чат можно обмениваться подготовленными пакетами и JSON-предложениями.</p><p class="annotation">Для API распакуй архив проекта. Скопируй .env.example в .env, укажи свой OPENAI_API_KEY и запусти из папки проекта:</p><pre class="json">python3 server.py</pre><p class="annotation">После запуска открой адрес, который напечатает сервер. Ключ остаётся на сервере. Python 3.10+; сторонние пакеты не нужны. Модель задаётся OPENAI_MODEL. API использует отдельный биллинг. Реальный ответ модели требует рабочего ключа; в поставке ключа нет.</p><p class="annotation">Сервер рассчитан на свой компьютер: проверка Origin и токена сессии, ограничение запросов. Если он доступен по внешнему адресу, задай WORKSHOP_ACCESS_KEY в .env — без ключа ИИ-запросы с чужих адресов отклоняются. Это не многопользовательский сервис.</p></section></div>
<section class="panel" style="margin-top:20px"><h2>История изменений</h2><div class="timeline">${D.audit.slice(-12).reverse().map(a=>`<div class="data-row"><span>${esc(a.label)}</span><span class="small muted">${esc(new Date(a.date).toLocaleString('ru-RU'))}</span></div>`).join('')||'<p class="annotation">После первого изменения здесь появится запись.</p>'}</div></section><section class="panel" style="margin-top:20px"><h2>Источники и границы</h2><p class="annotation">Маршруты и XP — авторская учебная структура, не аттестованный курс. Карточки не заменяют руководства оборудования, паспорта материалов и применимые местные нормы. Справочники ниже использованы для API и общих правил безопасности; ИИ-предложения не проходят автоматическую техническую экспертизу.</p>${D.sources.map(s=>`<div class="data-row"><div><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a><div class="annotation">${esc(s.note)}</div></div></div>`).join('')}</section>`}
function hasOldSave(){try{return!!localStorage.getItem(OLD_KEY)}catch{return false}}
function safeUrl(s){try{const u=new URL(s);return['https:','http:'].includes(u.protocol)?esc(u.href):'#'}catch{return'#'}}
let lastFocused=null;
function modal(title,body,foot='',large=false){if(!$('#modal-root').innerHTML)lastFocused=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${large?'large':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><header class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button class="btn icon-only text" data-action="close-modal" aria-label="Закрыть">${ico('close')}</button></header><div class="modal-body">${body}</div>${foot?`<footer class="modal-foot">${foot}</footer>`:''}</section></div>`;document.body.style.overflow='hidden';$('#modal-root button')?.focus({preventScroll:true})}
function closeModal(){if(!$('#modal-root'))return;$('#modal-root').innerHTML='';document.body.style.overflow='';U.openModal=null;if(lastFocused?.isConnected)lastFocused.focus({preventScroll:true})}
function detailBox(title,text){return`<div class="detail-box"><h4>${esc(title)}</h4><p>${esc(text)}</p></div>`}
function masteryBox(s){const g=prog(s.id),m=D.mastery[s.id];return`<div class="mastery-box ${g.status}"><div class="row between"><div><div class="eyebrow">${g.mastered?'НАВЫК ОСВОЕН':'ЧТО ЗНАЧИТ «ОСВОЕН»'}</div><h4>${g.mastered?'Отмечен '+esc(fmtDate(g.date)):g.criteria?`Отмечено ${g.checks} из ${g.criteria}`:'Критерии не заданы'}</h4></div>${btn(g.mastered?'Снять отметку':'Навык освоен','toggle-mastered',s.id,g.mastered?'sm':'sm primary',g.mastered?'undo':'check')}</div>${s.criteria.length?`<div class="checklist">${s.criteria.map((t,i)=>`<label class="checkline ${m?.checks.includes(i)?'checked':''}"><input type="checkbox" data-mastery-check="${i}" data-skill="${esc(s.id)}" ${m?.checks.includes(i)?'checked':''}><span>${esc(t)}</span></label>`).join('')}</div>`:'<p class="annotation">Добавь критерии в редакторе карточки, чтобы видеть, что осталось.</p>'}${!g.mastered&&g.criteria&&g.checks===g.criteria?'<p class="annotation">Все критерии отмечены — можно закрыть навык.</p>':''}${s.risk==='pro'?'<p class="annotation">Для этой области галочка означает освоенную учебную часть, а не допуск к самостоятельной работе.</p>':''}</div>`}
function openSkill(id){const s=getSkill(id);if(!s)return;U.openModal={type:'skill',id};const n=Core.skillStats(D,id),records=D.events.filter(e=>e.allocations.some(a=>a.skillId===id));const projects=activeProjects().filter(p=>p.skillIds.includes(id));modal(s.title,`<div class="row">${bTag(s.branchId)}${tag(s.module)}${riskTag(s.risk)}${tag(STAGE[s.stage])}${n.stale?tag('Освежить прошлый опыт','gold'):''}${s.archived?tag('В архиве','red'):''}</div><div class="detail-grid" style="margin-top:20px"><div>${masteryBox(s)}${detailBox('Цель',s.goal)}${detailBox('Учебное действие',s.exercise)}${detailBox('Как проверить результат',s.proof)}${s.risk==='pro'?'<div class="notice danger"><b>Не открывается количеством XP</b><p>Эта область предполагает профильное обучение, профессиональное исполнение или проверку. Учебное понимание не равно самостоятельному безопасному выполнению.</p></div>':''}<div class="section-head"><h3>След опыта</h3></div><div class="timeline">${records.map(e=>eventLine(e)).join('')||'<p class="annotation">Подтверждённого опыта пока нет. Это нормально.</p>'}</div></div><aside><div class="detail-box"><h4>Только связанный опыт</h4>${Object.entries(KIND).map(([k,t])=>`<div class="data-row"><span class="small">${t}</span><b>${n[k]}</b></div>`).join('')}</div><div class="detail-box"><h4>Предварительно полезно</h4>${s.prerequisites.length?s.prerequisites.map(id=>`<div>${sLink(id)}</div>`).join(''):'<p>Специальные предпосылки не заданы.</p>'}</div><div class="detail-box"><h4>Инструменты под задачу</h4>${s.toolIds.map(id=>{const t=getTool(id),st=D.inventory[id];const b=st==='have'?tag('✓ есть','green'):(st==='want'?tag('хочу','gold'):(st==='borrow'?tag('одолжить','blue'):''));return`<div class="row between" style="margin-bottom:5px"><span>${esc(t?.title||id)}</span>${b}</div>`}).join('')||'<p>Специальный набор не указан.</p>'}</div><div class="field"><label for="skill-goal">Моё намерение · без XP</label><select id="skill-goal"><option value="">Не назначено</option>${[['explore','Познакомиться'],['repeat','Освежить практикой'],['deepen','Углубиться'],['later','Не сейчас']].map(([k,t])=>`<option value="${k}" ${D.goals[id]===k?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="skill-note">Личная заметка</label><textarea id="skill-note" placeholder="Что интересно, что пока непонятно…">${esc(D.notes[id]||'')}</textarea></div>${btn('Сохранить заметку и цель','save-skill-note',id,'sm')}
</aside></div>${projects.length?`<div class="section-head"><h3>Проекты с этим навыком</h3></div><div class="row">${projects.map(p=>btn(esc(p.title),'project',p.id,'sm')).join('')}</div>`:''}`,btn('Редактировать карточку','edit-skill',id,'','edit')+btn('Записать реальный опыт','skill-event',id,'primary','plus'),true)}
function openProject(id){const p=getProject(id);if(!p)return;const status=Core.projectState(D,id),w=D.work[id]||{status:'planned',steps:[],note:''};U.openModal={type:'project',id};modal(p.title,`<div class="row">${p.branchIds.map(bTag).join('')}${riskTag(p.risk)}${tag(PS[status],status==='done'?'green':'gold')}${tag(p.kind==='theory'?'Теоретический квест':'Практический квест','blue')}</div><p class="muted" style="margin-top:14px;font-size:14px">${esc(p.description)}</p><div class="detail-grid" style="margin-top:20px"><div><h3>Этапы</h3><p class="annotation">Это чек-лист проекта, не техническая инструкция. Галочки не начисляют XP.</p><div class="checklist">${p.steps.map((t,i)=>`<label class="checkline ${w.steps.includes(i)?'checked':''}"><input type="checkbox" data-project-step="${i}" data-project="${esc(id)}" ${w.steps.includes(i)||status==='done'?'checked':''} ${status==='done'?'disabled':''}><span>${esc(t)}</span></label>`).join('')}</div><div class="detail-box"><h4>Критерии завершения</h4><ol class="steps">${p.checks.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div>${p.risk==='pro'?'<div class="notice danger"><b>Нужна соответствующая подготовка</b><p>Самостоятельная работа с газом, сетью, несущими конструкциями, давлением и высотой не следует из прогресса в игре. Отделяй свой учебный вклад от работы специалиста.</p></div>':''}</div><aside><div class="detail-box"><h4>Навыки, к которым относится работа</h4>${p.skillIds.map(id=>`<div>${sLink(id)}</div>`).join('')}</div><div class="detail-box"><h4>Оснащение</h4>${p.toolIds.map(id=>{const t=getTool(id),st=D.inventory[id];const b=st==='have'?tag('✓ есть','green'):(st==='want'?tag('хочу','gold'):(st==='borrow'?tag('одолжить','blue'):''));return`<div class="row between" style="margin-bottom:5px"><span>${esc(t?.title||id)}</span>${b}</div>`}).join('')||'<p>Уточняется под проект.</p>'}</div><div class="field"><label for="project-note">Заметки и фактические решения</label><textarea id="project-note">${esc(w.note)}</textarea></div>${btn('Сохранить заметку','save-project-note',id,'sm')}${status!=='done'?`<div class="field" style="margin-top:15px"><label>Состояние · без XP</label><select data-project-status="${esc(id)}">${['planned','active','paused'].map(k=>`<option value="${k}" ${w.status===k?'selected':''}>${PS[k]}</option>`).join('')}</select></div>`:''}</aside></div>${status==='done'?`<div class="notice" style="margin-top:16px"><b>Есть подтверждение в журнале</b><div class="timeline">${D.events.filter(e=>e.projectId===id).map(e=>eventLine(e)).join('')}</div></div>`:''}`,btn('Редактировать','edit-project',id,'','edit')+(status==='done'?btn('Закрыть','close-modal','','primary'):btn('В работу · без XP','start-project',id,'')+btn(p.kind==='theory'?'Изучено — записать результат':'Завершил — записать результат','finish-project',id,'primary','check')),true)}
function openEvent(id){const e=D.events.find(x=>x.id===id);if(!e)return;U.openModal={type:'event',id};modal(e.title,`<div class="row">${tag(KIND[e.kind],e.kind==='theory'?'blue':'green')}${e.stale?tag('Освежить','gold'):''}${tag(fmtDate(e.date))}</div><div style="margin-top:17px">${detailBox('Что действительно сделано',e.description)}${detailBox('Основание записи',e.evidence)}${e.dateLabel?detailBox('О дате',e.dateLabel):''}</div><h3>Распределение опыта</h3>${e.allocations.map(a=>`<div class="data-row">${sLink(a.skillId)}<b>+${a.points} XP</b></div>`).join('')}${e.projectId?`<p class="annotation">Связанный проект: <button class="linkbutton" data-action="project" data-id="${esc(e.projectId)}">${esc(getProject(e.projectId)?.title||e.projectId)}</button></p>`:''}<p class="annotation">Одна запись связана с несколькими навыками. Её XP не удваиваются отдельным бонусом за проект.</p>`,btn('Удалить запись…','delete-event',id,'danger')+btn('Уточнить запись','edit-event',id,'','edit')+btn('Закрыть','close-modal','','primary'))}
function picker(ids,points=false,allocations=[]){return`<input type="search" id="pick-search" placeholder="Фильтр списка навыков" style="margin-bottom:8px"><div class="skill-pick" id="skill-picker">${activeSkills().sort((a,b)=>ids.includes(b.id)-ids.includes(a.id)).map(s=>{const a=allocations.find(x=>x.skillId===s.id);return`<label data-pick-text="${esc(Core.norm(s.title+' '+getBranch(s.branchId)?.title))}"><input type="checkbox" data-pick-id="${esc(s.id)}" ${ids.includes(s.id)?'checked':''}><span class="pick-name">${esc(s.title)} <span class="small muted">· ${esc(getBranch(s.branchId)?.title)}</span></span>${points?`<input type="number" min="1" max="30" value="${a?.points||5}" data-point-id="${esc(s.id)}" aria-label="XP: ${esc(s.title)}">`:''}</label>`}).join('')}</div>`}
function openEventForm(opts={}){const existing=opts.eventId?D.events.find(e=>e.id===opts.eventId):null;const p=opts.projectId?getProject(opts.projectId):existing?.projectId?getProject(existing.projectId):null;const kind=existing?.kind||opts.kind||p?.kind||'practice';const chosen=existing?.allocations.map(a=>a.skillId)||opts.skillIds||p?.skillIds||[];U.formEvent={editId:existing?.id||null,projectId:p?.id||null};U.fresh=[];modal(existing?'Уточнить запись опыта':'Записать подтверждённый опыт',`<div class="notice"><b>Не добавляй сюда текущее дело ради галочки</b><p>Практика — только после завершения. Если работа продолжается, сохрани её в проектах. Прекращённая попытка — для действительно остановленной работы.</p></div><div class="cards two" style="margin-top:18px"><div class="field"><label for="event-kind">Вид записи</label><select id="event-kind">${Object.entries(KIND).map(([k,t])=>`<option value="${k}" ${kind===k?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label for="event-date">Дата · очисти, если точно неизвестна</label><input id="event-date" type="date" value="${esc(existing?existing.date||'':today())}"></div></div><div class="field"><label for="event-title">Короткое название</label><input id="event-title" maxlength="160" value="${esc(existing?.title||p?.title||'')}" placeholder="Собрал полку / прошёл курс / остановил попытку"></div><div class="field"><label for="event-description">Что сделал, что получилось и где остановился</label><textarea id="event-description" maxlength="6000" placeholder="Конкретный результат и твой вклад. Не включай операции, которые только обсуждал.">${esc(existing?.description||'')}</textarea></div><div class="field"><label for="event-evidence">Подтверждение / наблюдение / ссылка / вывод</label><textarea id="event-evidence" maxlength="3000" placeholder="Например: полка установлена, крепёж проверен; фото сохранено у меня. Или: просмотрел курс целиком, пока без практики.">${esc(existing?.evidence||'')}</textarea></div><div class="row" style="margin-bottom:16px"><label class="checkline"><input id="event-stale" type="checkbox" ${existing?.stale?'checked':''}><span>Давно не практиковался — отметить «освежить»</span></label></div><div class="row between"><h3>Какие навыки действительно использовал</h3>${btn('Подобрать с ИИ','form-ai','skills','sm','spark')}</div><p class="annotation" id="form-ai">Опиши работу выше и нажми «Подобрать с ИИ»: он отметит подтверждённые навыки и XP, а если подходящего нет — предложит новый в нужной ветке и подветке. Уйдут только текст записи и список навыков; ничего не сохранится, пока не нажмёшь «${existing?'Сохранить уточнение':'Добавить в журнал'}».</p><p class="annotation" id="event-cap">Можно снять неподтверждённые навыки. Предел за запись: ${Core.CAPS[kind]} XP. На один навык: 1–30.</p><div style="margin-top:11px" id="event-skills">${picker(chosen,true,existing?.allocations||chosen.map(id=>({skillId:id,points:kind==='theory'?2:5})))}</div><div class="notice warn" style="margin-top:17px"><label class="checkline"><input type="checkbox" id="event-confirm"><span>Подтверждаю, что запись описывает реальный результат или изученный материал, а не план. Для остановленной попытки работа действительно прекращена. Чужую работу не записываю как собственное выполнение.</span></label></div>${p?`<p class="annotation">Связь с проектом: ${esc(p.title)}. По возможности оставь только те навыки, которые действительно применил.</p>`:''}`,btn('Отмена','close-modal','','')+btn(existing?'Сохранить уточнение':'Добавить в журнал','save-event','','primary','check'),true)}
function selectedSkills(){return $$('[data-pick-id]:checked').map(x=>x.dataset.pickId)}
function saveEventForm(){assert($('#event-confirm').checked,'Подтверди факт работы или изучения');const kind=$('#event-kind').value,ids=selectedSkills(),fresh=checkedFresh();assert(ids.length||fresh.length,'Выбери хотя бы один реально затронутый навык');const edit=D.events.find(e=>e.id===U.formEvent.editId);const date=$('#event-date').value||null;const e={id:edit?.id||uid('event'),title:$('#event-title').value.trim(),kind,date,dateLabel:date?'Дата указана пользователем':'Точная дата не указана',description:$('#event-description').value.trim(),evidence:$('#event-evidence').value.trim(),allocations:[...fresh.map(s=>({skillId:s.id,points:+$(`[data-fresh-point="${s.id}"]`).value})),...ids.map(id=>({skillId:id,points:+$(`[data-point-id="${id}"]`).value}))],projectId:U.formEvent.projectId,stale:$('#event-stale').checked,toolIds:edit?.toolIds||(U.formEvent?.projectId?getProject(U.formEvent.projectId)?.toolIds||[]:[]),source:'user',createdAt:edit?.createdAt||new Date().toISOString()};Core.validateEvent(e,{...D,skills:[...D.skills,...fresh]},SCHEMA);assert(!D.events.some(x=>x.id!==e.id&&Core.eventFingerprint(x)===Core.eventFingerprint(e)),'Такая запись уже есть. Повторный зачёт не выполнен.');commit((edit?'Уточнён опыт: ':'Добавлен опыт: ')+e.title+(fresh.length?' · новых навыков: '+fresh.length:''),()=>{D.skills.push(...fresh);if(edit)D.events[D.events.findIndex(x=>x.id===e.id)]=e;else D.events.push(e)});closeModal();go('journal');toast(fresh.length?`Запись сохранена, на карту добавлено новых навыков: ${fresh.length}.`:'Запись сохранена. Связанные навыки обновились из журнала.')}
// AI helpers inside the event and project forms: the model sees the form text and the whole skill index and answers
// once, without questions (modes «skills» / «project», src/*.schema.json). The answer only fills the form;
// nothing is stored until the user saves it.
function eventDraft(){return{title:$('#event-title').value.trim(),kind:$('#event-kind').value,date:$('#event-date').value||null,description:$('#event-description').value.trim(),evidence:$('#event-evidence').value.trim(),projectId:U.formEvent.projectId}}
function indexForAI(){return{revision:D.revision,branches:activeBranches().map(b=>({id:b.id,title:b.title,subtitle:b.subtitle})),skillsIndex:activeSkills().map(s=>({id:s.id,branchId:s.branchId,module:s.module,title:s.title}))}}
async function askAI(mode,message,context,what){assert(!U.aiBusy,'Запрос уже выполняется');const h=await health();assert(h.accessGranted!==false,'Сервер открыт по публичному адресу, поэтому ИИ закрыт ключом доступа. Введи ключ в разделе «ИИ-наставник».');assert(h.configured,'На сервере нет OPENAI_API_KEY. Настрой .env; ключ не нужно вставлять в HTML.');
 U.aiBusy=true;const note=$('#form-ai'),button=$('[data-action="form-ai"]'),started=Date.now(),tick=()=>{if(note.isConnected)note.textContent=`ИИ ${what}… ${Math.round((Date.now()-started)/1000)} с. Обычно 5–60 с; пока ничего не меняется.`};tick();const timer=setInterval(tick,1000);button.disabled=true;
 try{const r=await fetch('/api/propose',{method:'POST',headers:{'Content-Type':'application/json','X-Workshop-Token':h.sessionToken,...accessHeaders()},body:JSON.stringify({mode,scope:'all',message,context}),signal:AbortSignal.timeout(150000)});let body;try{body=await r.json()}catch{throw Error('Сервер вернул нечитаемый ответ')}assert(r.ok,body.error||'Ошибка API');if(!note.isConnected)return null;Core.safeTree(body.proposal);Core.validateSchema(body.proposal,SUGGEST[mode]);return body.proposal}
 catch(e){if(note.isConnected)note.textContent='Ошибка: '+(e.name==='TimeoutError'?'время ожидания истекло. Можно заполнить вручную.':e.message);throw e}
 finally{clearInterval(timer);U.aiBusy=false;if(button.isConnected)button.disabled=false}}
// New skills from the model: only in active branches, with the texts a card needs; colliding IDs get a fresh one.
function freshFromAI(list){const branches=new Set(activeBranches().map(b=>b.id)),out=[];for(const {points,...s} of clone(list).slice(0,3)){s.criteria=s.criteria.filter(x=>x.trim());if(!branches.has(s.branchId)||![s.title,s.module,s.goal,s.exercise,s.proof].every(x=>x.trim())||s.criteria.length<2)continue;if(D.skills.some(x=>x.id===s.id)||out.some(([x])=>x.id===s.id))s.id=uid('skill');Object.assign(s,{toolIds:[],prerequisites:[],archived:false});out.push([s,points])}return out}
function checkedFresh(){return(U.fresh||[]).filter(s=>$(`[data-fresh-id="${s.id}"]`)?.checked)}
function freshSkillsBlock(fresh,allocs,hint){if(!fresh.length)return'';return`<div class="notice" style="margin-bottom:12px"><b>Новые навыки от ИИ</b><p>Таких нет в каталоге. ${hint}</p><div class="skill-pick" style="max-height:none;margin-top:8px">${fresh.map(s=>{const a=allocs?.find(x=>x.skillId===s.id);return`<label><input type="checkbox" data-fresh-id="${esc(s.id)}" checked><span class="pick-name">${esc(s.title)} <span class="small muted">· ${esc(getBranch(s.branchId)?.title)} / ${esc(s.module)}</span><br><span class="small muted">${esc(s.goal)}</span></span>${allocs?`<input type="number" min="1" max="30" value="${a?.points||5}" data-fresh-point="${esc(s.id)}" aria-label="XP: ${esc(s.title)}">`:''}</label>`}).join('')}</div></div>`}
async function suggestSkills(){const f=eventDraft();assert(f.description.length>=8,'Сначала опиши, что сделал: по описанию ИИ подберёт навыки');const pr=getProject(f.projectId);
 const p=await askAI('skills',`Подбери навыки для этой записи опыта.\n\nЗапись: ${JSON.stringify(f)}`,{...indexForAI(),caps:Core.CAPS,project:pr?{id:pr.id,title:pr.title,kind:pr.kind,skillIds:pr.skillIds}:null},'подбирает навыки');if(!p)return;
 const known=new Set(activeSkills().map(s=>s.id)),allocs=[];for(const a of p.allocations)if(known.has(a.skillId)&&!allocs.some(x=>x.skillId===a.skillId))allocs.push(a);
 const fresh=freshFromAI(p.newSkills);for(const [s,points] of fresh)allocs.push({skillId:s.id,points});U.fresh=fresh.map(([s])=>s);
 const cap=Core.CAPS[$('#event-kind').value],sum=allocs.reduce((n,a)=>n+a.points,0);
 $('#event-skills').innerHTML=freshSkillsBlock(U.fresh,allocs,'Отмеченные появятся на карте вместе с этой записью; за саму карточку XP не даётся.')+picker(allocs.map(a=>a.skillId).filter(id=>known.has(id)),true,allocs);
 $('#form-ai').textContent=allocs.length?`ИИ предложил: ${allocs.length} ${skillWord(allocs.length)}, ${sum} XP. ${p.summary} Проверь отметки и XP, сними лишнее — сохранится только после твоего подтверждения.${sum>cap?` Сумма больше предела ${cap} XP — уменьши очки.`:''}`:`ИИ не предложил навыков. Допиши, что именно делал руками, и нажми ещё раз, или отметь навыки вручную. ${p.summary}`}
// Existing cards keep the texts the user already wrote; a new card takes the whole suggestion.
async function suggestSkillCard(){const isNew=!U.editSkill,f={title:$('#edit-s-title').value.trim(),branchId:$('#edit-s-branch').value,module:$('#edit-s-module').value.trim(),goal:$('#edit-s-goal').value.trim(),exercise:$('#edit-s-exercise').value.trim(),proof:$('#edit-s-proof').value.trim(),criteria:lines('edit-s-criteria')};assert((f.title+' '+f.goal).trim().length>=4,'Сначала напиши название навыка');
 const p=await askAI('skill',`Заполни карточку навыка.\n\nЧерновик: ${JSON.stringify(f)}`,{...indexForAI(),tools:D.tools.map(t=>({id:t.id,title:t.title}))},'заполняет карточку');if(!p)return;
 const put=(sel,v)=>{const el=$(sel);if(isNew||!el.value.trim()||(sel==='#edit-s-module'&&el.value==='Новая подветка'))el.value=v};
 if(isNew&&getBranch(p.branchId)&&!getBranch(p.branchId).archived)$('#edit-s-branch').value=p.branchId;
 put('#edit-s-title',f.title||p.title);put('#edit-s-module',p.module);put('#edit-s-goal',p.goal);put('#edit-s-exercise',p.exercise);put('#edit-s-proof',p.proof);put('#edit-s-criteria',p.criteria.filter(x=>x.trim()).slice(0,8).join('\n'));
 const rank={low:0,care:1,pro:2},risk=$('#edit-s-risk');if(isNew||rank[p.risk]>rank[risk.value])risk.value=p.risk;if(isNew)$('#edit-s-stage').value=p.stage;
 setMulti('edit-s-tools',new Set([...multiVal('edit-s-tools'),...p.toolIds.filter(id=>getTool(id))]));
 const known=new Set(activeSkills().map(s=>s.id));$('#skill-prereq').innerHTML=picker([...new Set([...selectedSkills(),...p.prerequisites])].filter(id=>known.has(id)&&id!==U.editSkill));
 $('#form-ai').textContent=`ИИ заполнил карточку${isNew?'':' (твои тексты не тронуты)'}. ${p.summary} Проверь и поправь — сохранится только по кнопке «Сохранить карточку».`}
function setMulti(id,values){for(const o of document.getElementById(id).options)o.selected=values.has(o.value)}
async function suggestProject(){const f={title:$('#edit-p-title').value.trim(),description:$('#edit-p-desc').value.trim(),kind:$('#edit-p-kind').value,steps:lines('edit-p-steps'),checks:lines('edit-p-checks')};assert((f.title+' '+f.description).trim().length>=8,'Сначала напиши название и пару слов о проекте');
 const p=await askAI('project',`Оформи мой проект.\n\nПроект: ${JSON.stringify(f)}`,{...indexForAI(),tools:D.tools.map(t=>({id:t.id,title:t.title}))},'оформляет проект');if(!p)return;
 const known=new Set(activeSkills().map(s=>s.id)),ids=[...new Set(p.skillIds.filter(id=>known.has(id)))];U.fresh=freshFromAI(p.newSkills).map(([s])=>s);
 $('#project-skills').innerHTML=freshSkillsBlock(U.fresh,null,'Отмеченные появятся на карте вместе с проектом.')+picker(ids);
 const branchIds=new Set([...p.branchIds,...U.fresh.map(s=>s.branchId)].filter(id=>getBranch(id)&&!getBranch(id).archived));if(branchIds.size)setMulti('edit-p-branches',branchIds);
 setMulti('edit-p-tools',new Set([...multiVal('edit-p-tools'),...p.toolIds.filter(id=>getTool(id))]));
 const kept=[];for(const k of ['steps','checks']){if(f[k].length)kept.push(k==='steps'?'этапы':'критерии');else $(`#edit-p-${k}`).value=p[k].join('\n')}
 const rank={low:0,care:1,pro:2},risk=$('#edit-p-risk');if(!U.editProject||rank[p.risk]>rank[risk.value])risk.value=p.risk;
 $('#edit-p-stage').value=p.stage;const size=$('#edit-p-size');if(!size.value.trim()||size.value==='Небольшой')size.value=p.size;
 $('#form-ai').textContent=`ИИ предложил: ${ids.length+U.fresh.length} ${skillWord(ids.length+U.fresh.length)}${U.fresh.length?` (новых ${U.fresh.length})`:''}, направления, ${kept.length?`а твои ${kept.join(' и ')} оставил как есть`:'этапы и критерии'}, инструменты, ступень и риск. ${p.summary} Проверь и поправь — проект сохранится только по кнопке «Сохранить проект».`}
function optionsMulti(items,selected,label=x=>x.title){return items.map(x=>`<option value="${esc(x.id)}" ${selected.includes(x.id)?'selected':''}>${esc(label(x))}</option>`).join('')}
const multiVal=id=>[...document.getElementById(id).selectedOptions].map(o=>o.value);
const lines=id=>document.getElementById(id).value.split('\n').map(x=>x.trim()).filter(Boolean);
function openSkillEditor(id=null,branchId=null){const s=id?getSkill(id):{branchId:branchId||'wood',module:'Новая подветка',title:'',goal:'',exercise:'',proof:'',criteria:[],risk:'care',stage:1,toolIds:[],prerequisites:[]};U.editSkill=id;modal(id?'Изменить навык':'Новый навык',`<div class="notice"><div class="row between"><b>Одна техника — один постоянный ID</b>${btn('Заполнить с ИИ','form-ai','skill','sm','spark')}</div><p id="form-ai">Переименование или перенос в другую подветку сохранят историю. Для новой карточки достаточно названия: «Заполнить с ИИ» предложит подветку, цель, упражнение, проверку, критерии, предпосылки и инструменты. ${id?'Заполненные тексты он не меняет. ':''}Ничего не сохранится до кнопки «Сохранить карточку».</p></div><div class="cards two" style="margin-top:18px"><div class="field"><label>Направление</label><select id="edit-s-branch">${branchOptions(s.branchId,false)}</select></div><div class="field"><label>Подветка</label><input id="edit-s-module" maxlength="100" value="${esc(s.module)}"></div></div><div class="field"><label>Название</label><input id="edit-s-title" maxlength="160" value="${esc(s.title)}"></div><div class="field"><label>Цель: что станет понятнее или начнёт получаться</label><textarea id="edit-s-goal">${esc(s.goal)}</textarea></div><div class="field"><label>Конкретное учебное действие</label><textarea id="edit-s-exercise">${esc(s.exercise)}</textarea></div><div class="field"><label>Как проверить результат</label><textarea id="edit-s-proof">${esc(s.proof)}</textarea></div><div class="field"><label>Критерии освоения · по одному на строку, до 8</label><textarea id="edit-s-criteria" placeholder="Могу …">${esc(s.criteria.join('\n'))}</textarea></div><div class="cards two"><div class="field"><label>Ступень маршрута</label><select id="edit-s-stage">${Object.entries(STAGE).map(([k,t])=>`<option value="${k}" ${+k===s.stage?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Риск</label><select id="edit-s-risk">${Object.entries(RISK).map(([k,t])=>`<option value="${k}" ${k===s.risk?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="field"><label>Инструменты · несколько значений через Ctrl / Cmd</label><select id="edit-s-tools" multiple size="6">${optionsMulti(D.tools,s.toolIds)}</select></div><div class="field"><label>Полезные предпосылки · без жёсткой блокировки</label><div id="skill-prereq">${picker(s.prerequisites)}</div></div>`,btn('Отмена','close-modal','','')+btn('Сохранить карточку','save-skill','','primary'),true)}
function saveSkillEditor(){const old=getSkill(U.editSkill),s={id:old?.id||uid('skill'),branchId:$('#edit-s-branch').value,module:$('#edit-s-module').value.trim(),title:$('#edit-s-title').value.trim(),goal:$('#edit-s-goal').value.trim(),exercise:$('#edit-s-exercise').value.trim(),proof:$('#edit-s-proof').value.trim(),criteria:lines('edit-s-criteria'),toolIds:multiVal('edit-s-tools'),prerequisites:selectedSkills(),risk:$('#edit-s-risk').value,stage:+$('#edit-s-stage').value,archived:old?.archived||false};assert(s.title&&s.module&&s.goal&&s.exercise&&s.proof,'Заполни название, подветку, цель, действие и критерий результата');assert(s.criteria.length<=8,'Не больше восьми критериев освоения');const reset=old&&D.mastery[s.id]?.checks.length&&JSON.stringify(old.criteria)!==JSON.stringify(s.criteria);commit((old?'Изменён':'Добавлен')+' навык: '+s.title,()=>{if(old)D.skills[D.skills.findIndex(x=>x.id===s.id)]=s;else D.skills.push(s);if(reset)D.mastery[s.id].checks=[]});closeModal();go('map',{branch:s.branchId});openSkill(s.id);toast(reset?'Карточка сохранена. Критерии изменились, поэтому их отметки сброшены; отметка «освоен» осталась.':'Карточка сохранена. За изменение каталога XP не начисляются.')}
function openProjectEditor(id=null){const p=id?getProject(id):{title:'',description:'',branchIds:U.projectBranch!=='all'?[U.projectBranch]:['wood'],skillIds:[],steps:[],checks:[],toolIds:[],stage:1,risk:'care',kind:'practice',size:'Небольшой'};U.editProject=id;U.fresh=[];modal(id?'Изменить проект':'Свой проект',`<div class="notice"><div class="row between"><b>Опиши идею — остальное предложит ИИ</b>${btn('Заполнить с ИИ','form-ai','project','sm','spark')}</div><p id="form-ai">Напиши название и описание, нажми «Заполнить с ИИ»: он подберёт навыки (и новые, если нужных нет), направления, этапы, критерии, инструменты, ступень и риск. Уйдут только эти тексты и списки каталога; ничего не сохранится до кнопки «Сохранить проект».</p></div><div class="field" style="margin-top:16px"><label>Название результата</label><input id="edit-p-title" maxlength="160" value="${esc(p.title)}" placeholder="Не «изучить дерево», а «сделать полку для книг»"></div><div class="field"><label>Описание и границы</label><textarea id="edit-p-desc">${esc(p.description)}</textarea></div><div class="cards two"><div class="field"><label>Направления · Ctrl / Cmd для нескольких</label><select id="edit-p-branches" multiple size="5">${optionsMulti(activeBranches(),p.branchIds)}</select></div><div class="stack"><div class="field"><label>Что засчитывается в конце</label><select id="edit-p-kind"><option value="practice" ${p.kind==='practice'?'selected':''}>Практический результат</option><option value="theory" ${p.kind==='theory'?'selected':''}>Изучение / теоретический результат</option></select></div><div class="field"><label>Ступень</label><select id="edit-p-stage">${Object.entries(STAGE).map(([k,t])=>`<option value="${k}" ${+k===p.stage?'selected':''}>${t}</option>`).join('')}</select></div></div></div><div class="cards two"><div class="field"><label>Этапы · по одному на строку</label><textarea id="edit-p-steps">${esc(p.steps.join('\n'))}</textarea></div><div class="field"><label>Критерии завершения · по одному на строку</label><textarea id="edit-p-checks">${esc(p.checks.join('\n'))}</textarea></div></div><div class="cards two"><div class="field"><label>Риск</label><select id="edit-p-risk">${Object.entries(RISK).map(([k,t])=>`<option value="${k}" ${k===p.risk?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Масштаб · своими словами</label><input id="edit-p-size" maxlength="80" value="${esc(p.size)}"></div></div><div class="field"><label>Инструменты · Ctrl / Cmd для нескольких</label><select id="edit-p-tools" multiple size="5">${optionsMulti(D.tools,p.toolIds)}</select></div><div class="field"><label>Связанные навыки</label><div id="project-skills">${picker(p.skillIds)}</div></div>`,btn('Отмена','close-modal','','')+btn('Сохранить проект','save-project','','primary'),true)}
function saveProjectEditor(){const old=getProject(U.editProject),fresh=checkedFresh(),p={id:old?.id||uid('quest'),title:$('#edit-p-title').value.trim(),description:$('#edit-p-desc').value.trim(),branchIds:multiVal('edit-p-branches'),skillIds:[...fresh.map(s=>s.id),...selectedSkills()],steps:lines('edit-p-steps'),checks:lines('edit-p-checks'),toolIds:multiVal('edit-p-tools'),stage:+$('#edit-p-stage').value,risk:$('#edit-p-risk').value,kind:$('#edit-p-kind').value,size:$('#edit-p-size').value.trim(),archived:old?.archived||false};commit((old?'Изменён':'Добавлен')+' проект: '+p.title+(fresh.length?' · новых навыков: '+fresh.length:''),()=>{D.skills.push(...fresh);if(old){D.projects[D.projects.findIndex(x=>x.id===p.id)]=p;if(D.work[p.id])D.work[p.id].steps=[]}else D.projects.push(p)});closeModal();go('projects');openProject(p.id);toast(old?'Проект обновлён. Старые отметки этапов сброшены, чтобы не привязать их к новым пунктам.':'Проект добавлен в каталог, без начисления опыта.')}
function openBranchEditor(id=null){const b=id?getBranch(id):{title:'',subtitle:'',group:'Материалы',color:'#739368',icon:'compass',goal:''};U.editBranch=id;modal(id?'Изменить направление':'Новое направление',`<div class="notice"><b>Первый уровень — достаточно общий</b><p>Сначала проверь, нет ли подходящего направления. Например, велосипед и мотоцикл — подветки транспорта, а не две новые профессии.</p></div><div class="field" style="margin-top:16px"><label>Название</label><input id="edit-b-title" maxlength="100" value="${esc(b.title)}"></div><div class="field"><label>Короткое описание</label><input id="edit-b-sub" maxlength="180" value="${esc(b.subtitle)}"></div><div class="field"><label>Большая цель</label><textarea id="edit-b-goal">${esc(b.goal)}</textarea></div><div class="cards two"><div class="field"><label>Группа</label><select id="edit-b-group">${['Фундамент','Материалы','Системы','Применение'].map(g=>`<option ${g===b.group?'selected':''}>${g}</option>`).join('')}</select></div><div class="field"><label>Цвет</label><input id="edit-b-color" type="color" value="${esc(b.color)}"></div></div><div class="field"><label>Значок</label><select id="edit-b-icon">${SCHEMA.$defs.branch.properties.icon.enum.map(k=>`<option value="${k}" ${k===b.icon?'selected':''}>${k}</option>`).join('')}</select></div>`,btn('Отмена','close-modal','','')+btn('Сохранить','save-branch','','primary'))}
function saveBranchEditor(){const old=getBranch(U.editBranch),b={id:old?.id||uid('branch'),title:$('#edit-b-title').value.trim(),subtitle:$('#edit-b-sub').value.trim(),group:$('#edit-b-group').value,color:$('#edit-b-color').value,icon:$('#edit-b-icon').value,goal:$('#edit-b-goal').value.trim(),archived:false};assert(b.title&&b.goal,'Нужны название и цель направления');commit((old?'Изменено':'Добавлено')+' направление: '+b.title,()=>{if(old)D.branches[D.branches.findIndex(x=>x.id===b.id)]=b;else D.branches.push(b)});closeModal();go('map',{branch:b.id})}
function openToolEditor(id=null){const t=id?getTool(id):{id:'',title:'',es:'',description:'',branchIds:U.toolBranch!=='all'?[U.toolBranch]:['base']};const curStatus=id?(D.inventory[id]||'have'):'have';U.editTool=id;const isCustom=id&&!SEED.tools.some(x=>x.id===id);modal(id?'Изменить инструмент':'Новый инструмент',`<div class="notice"><b>Инструменты и мелочи мастерской</b><p>Добавляй всё, что есть дома или под рукой: отвёртки, уголки, крепёж, верёвку, скотч, герметик, перчатки. Инструмент связывается с ветками и сразу доступен для отметки наличия.</p></div><div class="field" style="margin-top:16px"><label>Название инструмента или материала</label><input id="edit-t-title" maxlength="120" value="${esc(t.title)}" placeholder="Например: Отвёртка крестовая PH2, или Монтажные уголки"></div><div class="cards two"><div class="field"><label>Международное название / примечание</label><input id="edit-t-es" maxlength="100" value="${esc(t.es||'')}" placeholder="cinta / destornillador"></div><div class="field"><label>Статус наличия</label><select id="edit-t-status">${toolStatuses().map(([k,n])=>`<option value="${k}" ${k===curStatus?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="field"><label>Для чего нужен и особенности</label><textarea id="edit-t-desc" maxlength="1000" placeholder="Назначение, размер, как используется или для каких работ подходит">${esc(t.description||'')}</textarea></div><div class="field"><label>Направления мастерской · выбери подходящие</label><select id="edit-t-branches" multiple size="5">${optionsMulti(activeBranches(),t.branchIds)}</select></div>`,btn('Отмена','close-modal','','')+(isCustom?btn('Удалить инструмент','delete-tool',id,'danger'):'')+btn('Сохранить инструмент','save-tool','','primary'),false)}
function saveToolEditor(){const old=getTool(U.editTool),title=$('#edit-t-title').value.trim(),desc=$('#edit-t-desc').value.trim(),es=$('#edit-t-es').value.trim(),branchIds=multiVal('edit-t-branches'),status=$('#edit-t-status').value;assert(title,'Введи название инструмента');assert(desc,'Добавь описание или назначение инструмента');assert(branchIds.length,'Выбери хотя бы одно направление мастерской');let id=old?.id;if(!id){const slug=Core.norm(title).slice(0,20).replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'tool';let candidate=(branchIds[0]||'base')+'.'+slug;if(D.tools.some(x=>x.id===candidate))candidate=uid('tool');id=candidate}const tool={id,title,es:es||title.toLowerCase(),description:desc,branchIds};commit((old?'Изменён':'Добавлен')+' инструмент: '+tool.title,()=>{if(old)D.tools[D.tools.findIndex(x=>x.id===id)]=tool;else D.tools.push(tool);D.inventory[id]=status});closeModal();render();toast(old?'Инструмент обновлён':'Инструмент добавлен в мастерскую')}
function deleteTool(id){const t=getTool(id);if(!t)return;const inSkills=activeSkills().filter(s=>s.toolIds.includes(id)),inProjects=activeProjects().filter(p=>p.toolIds.includes(id));assert(!inSkills.length,'Этот инструмент используется в навыках: '+inSkills.map(s=>s.title).join(', '));assert(!inProjects.length,'Этот инструмент используется в проектах: '+inProjects.map(p=>p.title).join(', '));commit('Удалён инструмент: '+t.title,()=>{D.tools=D.tools.filter(x=>x.id!==id);delete D.inventory[id]});closeModal();render();toast('Инструмент удалён')}
function contextForAI(){const scope=U.aiScope;const compactSkills=activeSkills().map(s=>({id:s.id,branchId:s.branchId,module:s.module,title:s.title,goal:s.goal,risk:s.risk,stage:s.stage,prerequisites:s.prerequisites,mastery:prog(s.id).status}));return{revision:D.revision,preferences:{purpose:'Для себя, дома и удовольствия; не профессия и не гонка.',completedOnly:true,currentWorkGivesXP:false,theorySeparate:true,attemptOnlyIfStopped:true,needsApproval:true,countsAreGameConvention:true,language:'ru',noInventedDates:true,smallFirstProjects:true},caps:Core.CAPS,branches:activeBranches(),skillsIndex:compactSkills,selectedSkills:scope==='all'?[]:activeSkills().filter(s=>s.branchId===scope),projectIndex:activeProjects().map(p=>({id:p.id,title:p.title,branchIds:p.branchIds,skillIds:p.skillIds,risk:p.risk,stage:p.stage})),selectedProjects:scope==='all'?[]:activeProjects().filter(p=>p.branchIds.includes(scope)),tools:D.tools.map(t=>({id:t.id,title:t.title})),events:D.events.map(e=>({id:e.id,title:e.title,kind:e.kind,date:e.date,description:e.description,evidence:e.evidence,allocations:e.allocations,projectId:e.projectId,stale:e.stale})),inProgress:Object.entries(D.work).map(([id,w])=>({id,status:w.status,note:w.note})),mastery:Object.entries(D.mastery).map(([id,m])=>({skillId:id,mastered:m.mastered,criteriaChecked:m.checks.length,criteriaTotal:getSkill(id)?.criteria.length||0})),focus:D.focus};}
function preparePackage(){assert(U.aiText.trim().length>=8,'Сначала напиши, что сделать или что было выполнено');const request={mode:U.mode,scope:U.aiScope,userRequest:U.aiText.trim(),context:contextForAI()};U.packageMode=U.mode;U.packageRevision=D.revision;U.chatPackage=AI_RULES+'\n\nЗАПРОС И КОНТЕКСТ:\n'+JSON.stringify(request,null,2)+'\n\nJSON SCHEMA ОТВЕТА:\n'+JSON.stringify(SCHEMA,null,2);render();toast('Подготовлен переносимый запрос. Можно скопировать или сохранить .txt.')}
async function copyText(text){assert(text,'Сначала подготовь запрос');try{await navigator.clipboard.writeText(text);toast('Скопировано')}catch{modal('Текст для копирования',`<p class="annotation">Буфер обмена недоступен в этом режиме браузера. Выдели текст и скопируй, либо сохрани .txt.</p><textarea id="copy-fallback" style="min-height:330px">${esc(text)}</textarea>`,btn('Сохранить .txt','download-package','','primary'));$('#copy-fallback').focus();$('#copy-fallback').select()}}
function parseProposal(text){assert(text.length<2_000_000,'Ответ слишком большой');let clean=text.trim();if(clean.startsWith('```'))clean=clean.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');let p;try{p=JSON.parse(clean)}catch{throw Error('Не удалось прочитать JSON. Вставь один JSON-объект ответа, без пояснений до или после.')}Core.safeTree(p);Core.validateSchema(p,SCHEMA);if(U.packageMode&&U.packageMode!=='experience')assert(!p.operations.some(o=>o.type==='add_event'),'Запрос был про учебный план, поэтому начисление опыта в его ответе заблокировано');assert(p.baseRevision===D.revision,`Устаревший ответ: ревизия ${p.baseRevision}, сейчас ${D.revision}. Подготовь новый запрос.`);assert(!D.appliedProposalIds.includes(p.id),'Это предложение уже применено');U.proposal=p;U.proposalSelected=p.operations.map(o=>o.id);closeModal();U.page='mentor';render();setTimeout(()=>$('#proposal-section')?.scrollIntoView({behavior:'smooth',block:'start'}),80)}
function accessHeaders(){let k='';try{k=localStorage.getItem(ACCESS_KEY)||''}catch{}return k?{'X-Workshop-Key':k}:{}}
async function health(){assert(location.protocol==='http:'||location.protocol==='https:','Для API открой игру через локальный server.py, а не как file://. Ручной обмен с чатом доступен прямо здесь.');const r=await fetch('/api/health',{headers:{Accept:'application/json',...accessHeaders()},signal:AbortSignal.timeout(8000)});assert(r.ok,'Локальный API-сервер не ответил. Запусти server.py из архива.');const h=await r.json();assert(h.app==='svoya-masterskaya','По этому адресу другой сервер');U.health=h;render();return h}
async function requestAI(){assert(!U.aiBusy,'Запрос уже выполняется');assert(U.aiConsent,'Отметь согласие на отправку контекста и отдельный API-запрос');assert(U.aiText.trim().length>=8,'Опиши задачу подробнее');let h=await health();assert(h.accessGranted!==false,'Сервер открыт по публичному адресу, поэтому ИИ закрыт ключом доступа. Введи ключ выше.');assert(h.configured,'На сервере нет OPENAI_API_KEY. Настрой .env; ключ не нужно вставлять в HTML.');const request={mode:U.mode,scope:U.aiScope,message:U.aiText.trim(),context:contextForAI()};U.packageMode=U.mode;U.aiBusy=true;U.aiMessage='Запрос отправлен. Ничего не изменится до твоего одобрения.';render();try{const response=await fetch('/api/propose',{method:'POST',headers:{'Content-Type':'application/json','X-Workshop-Token':h.sessionToken,...accessHeaders()},body:JSON.stringify(request),signal:AbortSignal.timeout(150000)});let body;try{body=await response.json()}catch{throw Error('Сервер вернул нечитаемый ответ')};assert(response.ok,body.error||'Ошибка API');parseProposal(JSON.stringify(body.proposal));U.aiMessage='Предложение получено. Проверь текст, связи и реальность начисленного опыта.'}catch(e){U.aiMessage='Ошибка: '+(e.name==='TimeoutError'?'Время ожидания истекло. Состояние игры не изменено; API-запрос мог быть обработан и тарифицирован.':e.message)}finally{U.aiBusy=false;render()}}
function demoProposal(){const id=uid('skill-demo'),sid=id;const p={version:1,id:uid('proposal-demo'),baseRevision:D.revision,summary:'ДЕМОНСТРАЦИЯ, не ответ ИИ: как выглядит новая карточка для дерева. Никакого опыта не начисляется. Можно применить и затем отменить.',questions:[],operations:[{id:uid('op'),type:'add_skill',targetId:sid,reason:'Пример конкретной учебной карточки с критерием результата. Добавляется только после твоего одобрения.',data:{id:sid,branchId:'wood',module:'Проверка мебели',title:'Диагностика качающегося стола · демо',goal:'Отличать неровный пол от перекоса рамы и разной длины ножек.',exercise:'На безопасном ненагруженном столе описать качание в двух положениях. Сначала измерить, не подпиливать ножку наугад.',proof:'Есть наблюдения и проверяемая гипотеза; правка конструкции ещё не заявляется выполненной.',criteria:['Могу показать, в каких двух положениях стол качается, а в каких нет','Могу отличить неровный пол от разной длины ножек по замеру','Записал гипотезу до любой правки'],toolIds:['measure','square'],prerequisites:['base.diagnose','wood.square'],risk:'care',stage:2,archived:false}}]};U.proposal=p;U.proposalSelected=p.operations.map(x=>x.id);render();setTimeout(()=>$('#proposal-section')?.scrollIntoView({behavior:'smooth'}),50)}
function applyCurrentProposal(){const p=U.proposal;assert(p,'Нет предложения');const changed=Core.applyProposal(D,p,U.proposalSelected,SCHEMA);commit('Применено предложение: '+p.summary.slice(0,130),()=>{D=changed});U.proposal=null;U.proposalSelected=[];U.chatPackage='';U.packageMode=null;render();toast('Выбранные изменения применены. Можно отменить в «Правила и данные».')}
function updateWork(id,fn,label){const captured=$('#project-note')?.value;commit(label,()=>{D.work[id]||={status:'planned',steps:[],note:''};if(captured!==undefined)D.work[id].note=captured;fn(D.work[id])})}
function openPasteProposal(){modal('Вернуть ответ ИИ в игру',`<p class="annotation">Вставь JSON-предложение по подготовленному формату. Сначала проверим структуру. До отдельного нажатия «Применить» карта не меняется.</p><textarea id="proposal-input" style="min-height:300px" placeholder='{"version":1,"id":"proposal-...","baseRevision":${D.revision},...}'></textarea><p class="annotation">Можно также загрузить JSON-файл ответа. Это не импорт резервной копии.</p>${btn('Выбрать JSON-файл ответа','import-proposal','','sm')}`,btn('Отмена','close-modal','','')+btn('Проверить и показать','parse-proposal','','primary'))}
function filePicker(handler){const i=document.createElement('input');i.type='file';i.accept='.json,application/json';i.addEventListener('change',async()=>{try{const f=i.files[0];if(!f)return;assert(f.size<=8_000_000,'Файл больше 8 МБ');await handler(await f.text())}catch(e){toast(e.message,true)}});i.click()}
function requestImport(text){let o;try{o=JSON.parse(text)}catch{throw Error('Файл не является JSON')};Core.safeTree(o);const r=upgrade(o.state||o),next=r.state;U.importState=clone(next);modal('Восстановить резервную копию?',`<div class="notice warn"><b>Текущий профиль будет заменён</b><p>Сначала экспортируй его, если он нужен. Замена не объединяет две истории. Текущее состояние также сохранится для отмены.</p></div><div class="metrics"><div class="metric"><div class="metric-value">${next.skills.length}</div><div class="metric-label">навыков</div></div><div class="metric"><div class="metric-value">${next.events.length}</div><div class="metric-label">записей опыта</div></div></div><p class="annotation">Копия прошла проверку ID, зависимостей и ограничений опыта.${r.migrated?' Она из прошлой версии и будет обновлена: '+esc(reportText(r.report)||'добавлены отметки освоения.'):''}</p>`,btn('Экспортировать текущее','export','','')+btn('Отмена','close-modal','','')+btn('Восстановить','confirm-import','','primary'))}
const EXAMPLES={wood:{mode:'expand',scope:'wood',text:'Проработай дерево подробнее для домашней мебели новичка: дай несколько конкретных упражнений и проектов от полки до кровати. Не дублируй существующие карточки: лучше уточни их или добавь действительно недостающие. Учти, что инструменты покупаю под реальные задачи, а не все сразу. У каждого шага нужны цель, конкретное действие, критерий результата и предпосылки. Никакого начисления XP за планы.'},composite:{mode:'plan',scope:'composite',text:'Хочу путь к небольшим стеклопластиковым оболочкам. Предложи следующие маленькие учебные проекты, используя существующие навыки. Сначала понимание материала и безопасная зона, потом образцы и простая форма. Я начинающий, делаю для удовольствия. Никаких силовых, авиационных или пищевых изделий на старте; не назначай пропорции смолы без её инструкции. Опыт пока не начислять.'},experience:{mode:'experience',scope:'all',text:'Разбери только то, что я действительно закончил. Вот описание работы и результата: [замени этот текст своими фактами]. Предложи связанные навыки и умеренный XP, не выдумывай использованные инструменты и операции. Если из описания неясно, закончено ли дело, спроси и пока ничего не начисляй.'}};
// Central event delegation: user/AI strings are only rendered as escaped text, never handlers.
document.addEventListener('click',async ev=>{
 const el=ev.target.closest('[data-action]');if(!el)return;ev.preventDefault();const a=el.dataset.action,id=el.dataset.id;try{
 switch(a){
 case'nav':go(id,{branch:null});break;
 case'branch':go('map',{branch:id,mfilter:'all'});break;
 case'all-branches':go('map',{branch:null});break;
 case'branch-projects':go('projects',{projectBranch:id});break;
 case'focus':commit('Изменён фокус направлений',()=>{D.focus=D.focus.includes(id)?D.focus.filter(x=>x!==id):[...D.focus,id]});break;
 case'skill':openSkill(id);break;
 case'project':openProject(id);break;
 case'event':openEvent(id);break;
 case'new-event':openEventForm();break;
 case'skill-event':openEventForm({skillIds:[id]});break;
 case'edit-event':openEventForm({eventId:id});break;
 case'finish-project':openEventForm({projectId:id});break;
 case'save-event':saveEventForm();break;
 case'form-ai':await({project:suggestProject,skill:suggestSkillCard}[id]||suggestSkills)();break;
 case'delete-event':{const e=D.events.find(x=>x.id===id);modal('Удалить запись?',`<p>«${esc(e.title)}» будет удалена. Связанный XP исчезнет; статус проекта пересчитается. Это можно отменить.</p>`,btn('Отмена','close-modal','','')+btn('Удалить запись','confirm-delete-event',id,'danger'));break}
 case'confirm-delete-event':commit('Удалена запись опыта',()=>{D.events=D.events.filter(e=>e.id!==id)});closeModal();render();toast('Запись удалена, опыт пересчитан');break;
 case'save-skill-note':{const text=$('#skill-note').value,goal=$('#skill-goal').value;commit('Заметка и цель навыка',()=>{D.notes[id]=text;if(goal)D.goals[id]=goal;else delete D.goals[id]});toast('Цель и заметка сохранены, без начисления XP');break}
 case'start-project':updateWork(id,w=>w.status='active','Проект взят в работу: '+getProject(id).title);openProject(id);toast('Проект в работе. Пока без XP.');break;
 case'save-project-note':updateWork(id,()=>{},'Заметка проекта');toast('Заметка сохранена');break;
 case'new-skill':openSkillEditor(null,id);break;
 case'edit-skill':openSkillEditor(id);break;
 case'save-skill':saveSkillEditor();break;
 case'new-project':openProjectEditor();break;
 case'edit-project':openProjectEditor(id);break;
 case'save-project':saveProjectEditor();break;
 case'new-branch':openBranchEditor();break;
 case'edit-branch':openBranchEditor(id);break;
 case'save-branch':saveBranchEditor();break;
 case'new-tool':openToolEditor(null);break;
 case'edit-tool':openToolEditor(id);break;
 case'save-tool':saveToolEditor();break;
 case'delete-tool':deleteTool(id);break;
 case'tool-status-pill':U.toolStatus=id;render();break;
 case'toggle-tool-have':{
  const cur=D.inventory[id]||'unknown';
  const next=cur==='have'?'unknown':'have';
  const t=getTool(id);
  commit((next==='have'?'Есть в наличии: ':'Снята отметка наличия: ')+(t?.title||id),()=>{D.inventory[id]=next});
  break;
 }
 case'tool-skills':{
  const t=getTool(id);
  const matchedSkills=activeSkills().filter(s=>s.toolIds.includes(id));
  const matchedProjects=activeProjects().filter(p=>p.toolIds.includes(id));
  const st=D.inventory[id]||'unknown';
  modal(t.title,`<div class="row" style="margin-bottom:12px">${t.branchIds.map(bTag).join('')}${st==='have'?tag('✓ Есть у меня','green'):(st==='want'?tag('★ Хочу','gold'):'')}</div><p class="muted">${esc(t.description)}</p><div class="section-head"><h3>Связанные навыки (${matchedSkills.length})</h3></div><div style="margin-top:8px">${matchedSkills.map(skillRow).join('')||'<p class="annotation">Пока нет привязанных навыков.</p>'}</div>${matchedProjects.length?`<div class="section-head"><h3>Проекты с этим инструментом (${matchedProjects.length})</h3></div><div class="row" style="margin-top:8px">${matchedProjects.map(p=>btn(esc(p.title),'project',p.id,'sm')).join('')}</div>`:''}`,btn('Изменить инструмент','edit-tool',id,'','edit')+btn('Закрыть','close-modal','','primary'));
  break;
 }
 case'toggle-mastered':toggleMastered(id);if(U.openModal?.type==='skill'&&U.openModal.id===id)openSkill(id);break;
 case'mfilter':U.mfilter=id;render();break;
 case'save-access-key':{const v=$('#ai-access-key').value.trim();try{if(v)localStorage.setItem(ACCESS_KEY,v);else localStorage.removeItem(ACCESS_KEY)}catch{throw Error('Браузер не разрешил сохранить ключ')}await health();toast(U.health.accessGranted?'Ключ принят сервером':'Сервер не принял ключ',!U.health.accessGranted);break}
 case'old-save':{let raw='';try{raw=localStorage.getItem(OLD_KEY)||''}catch{}assert(raw,'Старого сохранения нет');download('masterskaya-before-v'+Core.VERSION+'.json',raw);break}
 case'close-modal':closeModal();break;
 case'server-save-now':{await sendServerSave('Ручное сохранение');await refreshBackups();render();toast('Сохранено на сервере в data/save.json и в Git');break}
 case'server-backup-now':{const res=await fetch('/api/backup',{method:'POST',headers:{'Content-Type':'application/json',...accessHeaders()},body:JSON.stringify({state:D,note:'Ручной снимок из интерфейса'})});const data=await res.json();assert(res.ok,data.error||'Ошибка создания копии');await refreshBackups();render();toast('Резервная копия создана: '+data.backupFile);break}
 case'server-git-commit':modal('Закоммитить прогресс в Git',`<p>Зафиксировать текущее состояние (ревизия ${D.revision}) в локальном Git-репозитории:</p><div class="field" style="margin-top:14px"><label for="git-msg-input">Сообщение коммита</label><input id="git-msg-input" value="Сохранение прогресса: ревизия ${D.revision}" maxlength="150"></div><p class="annotation">Коммит записывается в локальный репозиторий. Для отправки на GitHub/GitLab выполни <code>git push</code>.</p>`,btn('Отмена','close-modal')+btn('Закоммитить','confirm-git-commit','','primary','check'));break;
 case'confirm-git-commit':{const msg=$('#git-msg-input')?.value.trim()||`Прогресс: ревизия ${D.revision}`;const res=await fetch('/api/git-commit',{method:'POST',headers:{'Content-Type':'application/json',...accessHeaders()},body:JSON.stringify({message:msg})});const data=await res.json();assert(res.ok,data.error||'Ошибка Git-коммита');await refreshBackups();closeModal();render();toast(data.committed?'Коммит создан в Git!':'Изменения уже зафиксированы в Git');break}
 case'server-restore-backup':U.selectedBackup=id;modal('Восстановить из резервной копии?',`<p>Восстановить состояние игры из серверного файла:</p><pre class="json">${esc(id)}</pre><div class="notice warn"><b>Текущее состояние будет сохранено</b><p>Перед откатом сервер автоматически сделает снимок текущего состояния (pre-restore). Все текущие несохранённые правки будут заменены данными из выбранной копии.</p></div>`,btn('Отмена','close-modal')+btn('Подтвердить восстановление','confirm-server-restore',id,'danger'));break;
 case'confirm-server-restore':{const fn=U.selectedBackup||id;assert(fn,'Файл не выбран');const res=await fetch('/api/restore',{method:'POST',headers:{'Content-Type':'application/json',...accessHeaders()},body:JSON.stringify({filename:fn})});const data=await res.json();assert(res.ok,data.error||'Ошибка восстановления');const r=upgrade(data.save.state||data.save);D=r.state;undo=[];persist('Восстановление из '+fn);await refreshBackups();closeModal();render();toast('Состояние успешно восстановлено из '+fn);break}
 case'refresh-backups':await refreshBackups();render();toast('Статус сервера и список копий обновлены');break;
 case'theme':D.settings.theme=D.settings.theme==='light'?'dark':'light';persist();render();break;
 case'export':exportState();break;
 case'import-state':filePicker(requestImport);break;
 case'confirm-import':{const next=clone(U.importState);commit('Восстановлена резервная копия',()=>{D=next});corruptBackup='';saveError='';persist();U.proposal=null;closeModal();go('home');toast('Восстановлена резервная копия');break}
 case'undo':{assert(undo.length,'Нет сохранённого состояния для отмены');const previous=undo[undo.length-1];Core.validateState(previous,SCHEMA);undo.pop();const revision=D.revision+1;D=clone(previous);D.revision=revision;D.audit.push({id:uid('undo'),date:new Date().toISOString(),label:'Отменено последнее изменение'});persist();U.proposal=null;render();toast('Предыдущее состояние восстановлено');break}
 case'reset':modal('Вернуться к стартовому профилю?',`<p>Пользовательские карточки, записи, заметки и инвентарь будут заменены исходными. Сначала экспортируй копию. Сам HTML-файл не изменяется.</p>`,btn('Экспорт JSON','export','','')+btn('Отмена','close-modal','','')+btn('Вернуть старт','confirm-reset','','danger'));break;
 case'confirm-reset':commit('Возвращён стартовый профиль',()=>{D=clone(SEED)});U.proposal=null;closeModal();go('home');toast('Стартовый профиль восстановлен. Отмена доступна.');break;
 case'corrupt-backup':download('unread-original-backup.txt',corruptBackup,'text/plain');break;
 case'ai-branch':go('mentor');U.mode='expand';U.aiScope=id;U.aiText=`Проработай направление «${getBranch(id).title}» подробнее: конкретные учебные действия, критерии результата и полезные проекты. Не дублируй имеющиеся навыки, сохраняй ID при уточнении. Я учусь для себя и удовольствия. Опыт за планы не начислять.`;render();break;
 case'ai-example':{const x=EXAMPLES[id];U.mode=x.mode;U.aiScope=x.scope;U.aiText=x.text;render();break}
 case'health':await health();toast(U.health.configured?'Локальный сервер и API-ключ настроены. Действительность ключа проверится при запросе.':'Сервер доступен. Для ИИ нужен API-ключ.');break;
 case'ai-request':await requestAI();break;
 case'chat-package':preparePackage();break;
 case'copy-package':await copyText(U.chatPackage);break;
 case'download-package':assert(U.chatPackage,'Подготовь запрос');download('masterskaya-ai-request-r'+D.revision+'.txt',U.chatPackage,'text/plain;charset=utf-8');break;
 case'show-package':modal('Подготовленный запрос для чата',`<textarea readonly style="min-height:400px">${esc(U.chatPackage)}</textarea>`,btn('Скопировать','copy-package','','primary'),true);break;
 case'paste-proposal':openPasteProposal();break;
 case'parse-proposal':parseProposal($('#proposal-input').value);break;
 case'import-proposal':filePicker(text=>parseProposal(text));break;
 case'apply-proposal':applyCurrentProposal();break;
 case'discard-proposal':U.proposal=null;U.proposalSelected=[];render();toast('Предложение отброшено, состояние не менялось');break;
 case'proposal-json':modal('JSON предложения',`<pre class="json">${esc(JSON.stringify(U.proposal,null,2))}</pre>`,btn('Закрыть','close-modal','','primary'),true);break;
 case'demo-proposal':demoProposal();break;
 }
 }catch(e){console.warn('Action rejected:',e.message);toast(e.message,true)}
});
document.addEventListener('input',ev=>{const t=ev.target;switch(t.id){case'map-search':case'branch-search':case'project-search':case'journal-search':case'tool-search':U.search=t.value;render();break;case'ai-text':U.aiText=t.value;break;case'pick-search':{const q=Core.norm(t.value);$$('[data-pick-text]').forEach(l=>l.hidden=!l.dataset.pickText.includes(q));break}}});
document.addEventListener('change',ev=>{const t=ev.target;try{
 const bindings={'map-group':'group','map-status':'status','project-branch':'projectBranch','project-status':'status','journal-kind':'journalKind','tool-branch':'toolBranch','tool-status':'toolStatus','ai-mode':'mode','ai-scope':'aiScope'};
 if(bindings[t.id]){U[bindings[t.id]]=t.value;render();return}
 if(t.id==='project-simple'){U.simple=t.checked;render();return}if(t.id==='ai-consent'){U.aiConsent=t.checked;return}
 if(t.dataset.inventory){commit('Обновлён статус инструмента',()=>{D.inventory[t.dataset.inventory]=t.value});return}
 if(t.dataset.projectStep!==undefined){const id=t.dataset.project,i=+t.dataset.projectStep;updateWork(id,w=>{if(t.checked&&!w.steps.includes(i))w.steps.push(i);else if(!t.checked)w.steps=w.steps.filter(x=>x!==i);w.status='active'},'Отмечен этап проекта · без XP');openProject(id);return}
 if(t.dataset.masteryCheck!==undefined){const id=t.dataset.skill,i=+t.dataset.masteryCheck;setMastery(id,m=>{if(t.checked&&!m.checks.includes(i))m.checks.push(i);else if(!t.checked){m.checks=m.checks.filter(x=>x!==i)}},'Отмечен критерий освоения · без XP');openSkill(id);return}
 if(t.dataset.projectStatus){const id=t.dataset.projectStatus;updateWork(id,w=>w.status=t.value,'Изменено состояние проекта · без XP');openProject(id);return}
 if(t.dataset.proposalOp){if(t.checked)U.proposalSelected.push(t.dataset.proposalOp);else U.proposalSelected=U.proposalSelected.filter(x=>x!==t.dataset.proposalOp);return}
 if(t.id==='event-kind'){$('#event-cap').textContent=`Выбирай только подтверждённые навыки. Предел за запись: ${Core.CAPS[t.value]} XP. На один навык: 1–30.`}
}catch(e){toast(e.message,true)}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&$('#modal-root').innerHTML)closeModal();if(ev.key==='Tab'&&$('#modal-root').innerHTML){const items=$$('#modal-root button, #modal-root input, #modal-root select, #modal-root textarea, #modal-root a').filter(x=>!x.disabled&&!x.hidden&&x.offsetParent!==null);if(items.length){if(ev.shiftKey&&document.activeElement===items[0]){items[items.length-1].focus();ev.preventDefault()}else if(!ev.shiftKey&&document.activeElement===items[items.length-1]){items[0].focus();ev.preventDefault()}}}});
window.addEventListener('storage',ev=>{if(ev.key===KEY){saveError='Данные изменились в другой вкладке. Не редактируй обе одновременно: экспортируй нужную копию и перезагрузи страницу.';render()}});
window.addEventListener('beforeunload',()=>{
 if(serverSaveTimer){
  clearTimeout(serverSaveTimer);
  try{
   const blob=new Blob([JSON.stringify({app:'svoya-masterskaya',version:Core.VERSION,savedAt:new Date().toISOString(),note:'Сохранение при закрытии вкладки',state:D,undo:undo.slice(-3)})],{type:'application/json'});
   navigator.sendBeacon('/api/save',blob);
  }catch{}
 }
});
// A small inspectable test interface. It does not bypass validation or make API calls.
window.Workshop={getState:()=>clone(D),history:HISTORY,getUI:()=>({page:U.page,branch:U.branch,proposal:U.proposal}),validate:()=>Core.validateState(D,SCHEMA),schema:SCHEMA,seed:SEED,core:Core};
Core.validateState(D,SCHEMA);shell();render();if(migrationNote){persist();toast(migrationNote)}
initServerSync();
